#ifndef PCAP_INPUT_SOURCE_H
#define PCAP_INPUT_SOURCE_H

#include <cstddef>
#include <filesystem>
#include <functional>
#include <memory>
#include <string>
#include <vector>

#include "pcap_watch.h"

namespace pcap_input {

using callback_t = std::function<bool(const std::filesystem::path&)>;

enum class mode {
	watch_dir,
	file,
	dir,
};

struct config {
	mode input_mode{mode::watch_dir};
	std::filesystem::path watch_dir{"/tmp/stm/capture/"};
	std::filesystem::path file;
	std::filesystem::path dir;
	std::string pcap_prefix{"cap_"};
	std::size_t ring_file_count{10};
	std::size_t backlog_trend_threshold{1};
	bool stop_on_callback_failure{false};
};

class source {
public:
	virtual ~source() = default;
	virtual void set_callback(callback_t callback) = 0;
	virtual int run() = 0;
};

std::unique_ptr<source> make_source(config cfg);

} // namespace pcap_input

#endif /* PCAP_INPUT_SOURCE_H */
#include "pcap_input_source.h"

#include <algorithm>
#include <utility>

#include "trace.h"

namespace pcap_input {
namespace {

bool is_pcap_file(const std::filesystem::path &path) {
	const auto ext = path.extension().string();
	return ext == ".pcap" || ext == ".pcapng";
}

class watch_source : public source {
public:
	explicit watch_source(config cfg)
		: m_watch(pcap_watch::config{
			.watch_dir = cfg.watch_dir,
			.pcap_prefix = cfg.pcap_prefix,
			.ring_file_count = cfg.ring_file_count,
			.backlog_trend_threshold = cfg.backlog_trend_threshold,
			.stop_on_callback_failure = cfg.stop_on_callback_failure,
		}) {
	}

	void set_callback(callback_t callback) override {
		m_watch.set_callback(std::move(callback));
	}

	int run() override {
		return m_watch.run();
	}

private:
	pcap_watch m_watch;
};

class file_source : public source {
public:
	explicit file_source(config cfg)
		: m_file(std::move(cfg.file)) {
	}

	void set_callback(callback_t callback) override {
		m_callback = std::move(callback);
	}

	int run() override {
		if(!m_callback) {
			trace(0, "error: pcap input callback is not set");
			return 1;
		}
		if(m_file.empty()) {
			trace(0, "error: input file is not configured");
			return 1;
		}
		if(!std::filesystem::is_regular_file(m_file)) {
			trace(0, "error: input file is not a regular file: %s", m_file.string().c_str());
			return 1;
		}
		return m_callback(m_file) ? 0 : 1;
	}

private:
	std::filesystem::path m_file;
	callback_t m_callback;
};

class dir_source : public source {
public:
	explicit dir_source(config cfg)
		: m_dir(std::move(cfg.dir)) {
	}

	void set_callback(callback_t callback) override {
		m_callback = std::move(callback);
	}

	int run() override {
		if(!m_callback) {
			trace(0, "error: pcap input callback is not set");
			return 1;
		}
		if(m_dir.empty()) {
			trace(0, "error: input dir is not configured");
			return 1;
		}
		if(!std::filesystem::is_directory(m_dir)) {
			trace(0, "error: input dir is not a directory: %s", m_dir.string().c_str());
			return 1;
		}

		auto files = collect_pcaps();
		if(files.empty()) {
			trace(0, "warn: no pcap files found in %s", m_dir.string().c_str());
			return 0;
		}

		int rc = 0;
		for(const auto &file : files) {
			if(!m_callback(file)) {
				rc = 1;
			}
		}
		return rc;
	}

private:
	std::vector<std::filesystem::path> collect_pcaps() const {
		std::vector<std::filesystem::path> files;
		for(const auto &entry : std::filesystem::directory_iterator(m_dir)) {
			if(!entry.is_regular_file()) {
				continue;
			}
			if(is_pcap_file(entry.path())) {
				files.push_back(entry.path());
			}
		}
		std::sort(files.begin(), files.end());
		return files;
	}

	std::filesystem::path m_dir;
	callback_t m_callback;
};

} // namespace

std::unique_ptr<source> make_source(config cfg) {
	switch(cfg.input_mode) {
	case mode::watch_dir:
		return std::make_unique<watch_source>(std::move(cfg));
	case mode::file:
		return std::make_unique<file_source>(std::move(cfg));
	case mode::dir:
		return std::make_unique<dir_source>(std::move(cfg));
	}

	return nullptr;
}

