#include "dumpcap_command.h"

#include <algorithm>
#include <array>
#include <cctype>
#include <cstdio>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <sstream>
#include <stdexcept>
#include <utility>

namespace dumpcap {
namespace {

std::string trim(std::string_view value) {
	std::size_t first = 0;
	while(first < value.size() && std::isspace(static_cast<unsigned char>(value[first]))) {
		++first;
	}
	std::size_t last = value.size();
	while(last > first && std::isspace(static_cast<unsigned char>(value[last - 1]))) {
		--last;
	}
	return std::string(value.substr(first, last - first));
}

bool wildcard_match(std::string_view pattern, std::string_view value) {
	std::size_t p = 0;
	std::size_t v = 0;
	std::size_t star = std::string_view::npos;
	std::size_t match = 0;

	while(v < value.size()) {
		if(p < pattern.size() && (pattern[p] == value[v] || pattern[p] == '?')) {
			++p;
			++v;
		}
		else if(p < pattern.size() && pattern[p] == '*') {
			star = p++;
			match = v;
		}
		else if(star != std::string_view::npos) {
			p = star + 1;
			v = ++match;
		}
		else {
			return false;
		}
	}

	while(p < pattern.size() && pattern[p] == '*') {
		++p;
	}
	return p == pattern.size();
}

bool excluded(std::string_view name, const config &cfg) {
	if(!cfg.include_loopback && name == "lo") {
		return true;
	}

	const std::filesystem::path sys_net{"/sys/class/net"};
	if(std::filesystem::exists(sys_net)) {
		const auto sys_iface = sys_net / std::string(name);
		if(!std::filesystem::exists(sys_iface)) {
			return true;
		}
	}

	for(const auto &pattern : cfg.exclude_interfaces) {
		if(wildcard_match(pattern, name)) {
			return true;
		}
	}
	return false;
}

std::vector<std::string> read_string_array(const json &j, const char *key) {
	std::vector<std::string> out;
	if(!j.contains(key) || j[key].is_null()) {
		return out;
	}
	if(j[key].is_string()) {
		return split_csv(j[key].get<std::string>());
	}
	if(j[key].is_array()) {
		for(const auto &item : j[key]) {
			if(item.is_string()) {
				out.push_back(item.get<std::string>());
			}
		}
	}
	return out;
}

} // namespace

std::string shell_quote(std::string_view value) {
	std::string quoted;
	quoted.reserve(value.size() + 2);
	quoted.push_back('\'');
	for(char ch : value) {
		if(ch == '\'') {
			quoted += "'\\''";
		}
		else {
			quoted.push_back(ch);
		}
	}
	quoted.push_back('\'');
	return quoted;
}

std::vector<std::string> split_csv(std::string_view value) {
	std::vector<std::string> out;
	std::size_t start = 0;
	while(start <= value.size()) {
		const auto pos = value.find(',', start);
		const auto end = (pos == std::string_view::npos) ? value.size() : pos;
		auto item = trim(value.substr(start, end - start));
		if(!item.empty()) {
			out.push_back(std::move(item));
		}
		if(pos == std::string_view::npos) {
			break;
		}
		start = pos + 1;
	}
	return out;
}

int load_config_file(const std::filesystem::path &path, config &cfg) {
	if(path.empty()) {
		return 0;
	}

	std::ifstream in(path);
	if(!in) {
		std::cerr << "dumpcap_runner: failed to open config " << path << std::endl;
		return -1;
	}

	json root;
	try {
		in >> root;
	}
	catch(const std::exception &e) {
		std::cerr << "dumpcap_runner: failed to parse config " << path << ": " << e.what() << std::endl;
		return -1;
	}

	const json *j = &root;
	if(root.is_object() && root.contains("capture") && root["capture"].is_object()) {
		j = &root["capture"];
	}
	if(!j->is_object()) {
		std::cerr << "dumpcap_runner: config must be an object" << std::endl;
		return -1;
	}

	if(j->contains("program")) cfg.program = (*j)["program"].get<std::string>();
	if(j->contains("interfaces")) cfg.interfaces = read_string_array(*j, "interfaces");
	if(j->contains("auto_interfaces")) cfg.auto_interfaces = (*j)["auto_interfaces"].get<bool>();
	if(j->contains("include_loopback")) cfg.include_loopback = (*j)["include_loopback"].get<bool>();
	if(j->contains("exclude_interfaces")) cfg.exclude_interfaces = read_string_array(*j, "exclude_interfaces");
	if(j->contains("ring_duration_sec")) cfg.ring_duration_sec = (*j)["ring_duration_sec"].get<std::uint32_t>();
	if(j->contains("duration_sec")) cfg.ring_duration_sec = (*j)["duration_sec"].get<std::uint32_t>();
	if(j->contains("ring_files")) cfg.ring_files = (*j)["ring_files"].get<std::uint32_t>();
	if(j->contains("filesize_kb")) cfg.filesize_kb = (*j)["filesize_kb"].get<std::uint32_t>();
	if(j->contains("bpf_filter")) cfg.bpf_filter = (*j)["bpf_filter"].get<std::string>();
	if(j->contains("output")) cfg.output = (*j)["output"].get<std::string>();

	return 0;
}

std::vector<std::string> discover_interfaces(const std::string &program) {
	std::vector<std::string> out;
	const std::string command = shell_quote(program) + " -D 2>/dev/null";
	FILE *pipe = popen(command.c_str(), "r");
	if(pipe == nullptr) {
		return out;
	}

	std::array<char, 4096> buf{};
	while(fgets(buf.data(), static_cast<int>(buf.size()), pipe) != nullptr) {
		std::string line(buf.data());
		const auto dot = line.find('.');
		if(dot == std::string::npos) {
			continue;
		}
		std::string rest = trim(std::string_view(line).substr(dot + 1));
		if(rest.empty()) {
			continue;
		}
		std::istringstream iss(rest);
		std::string name;
		iss >> name;
		if(!name.empty()) {
			out.push_back(name);
		}
	}
	pclose(pipe);
	return out;
}

resolved_config resolve_config(const config &cfg) {
	resolved_config resolved;
	resolved.cfg = cfg;
	if(!cfg.interfaces.empty()) {
		resolved.interfaces = cfg.interfaces;
		return resolved;
	}
	if(!cfg.auto_interfaces) {
		throw std::runtime_error("no capture interfaces configured and auto_interfaces is false");
	}

	for(const auto &name : discover_interfaces(cfg.program)) {
		if(!excluded(name, cfg)) {
			resolved.interfaces.push_back(name);
		}
	}
	if(resolved.interfaces.empty()) {
		throw std::runtime_error("no capture interfaces resolved from dumpcap -D");
	}
	return resolved;
}

std::vector<std::string> build_argv(const resolved_config &resolved) {
	const auto &cfg = resolved.cfg;
	std::vector<std::string> argv;
	argv.push_back(cfg.program);
	for(const auto &iface : resolved.interfaces) {
		argv.push_back("-i");
		argv.push_back(iface);
	}
	if(!cfg.bpf_filter.empty()) {
		argv.push_back("-f");
		argv.push_back(cfg.bpf_filter);
	}
	if(cfg.ring_duration_sec > 0) {
		argv.push_back("-b");
		argv.push_back("duration:" + std::to_string(cfg.ring_duration_sec));
	}
	if(cfg.ring_files > 0) {
		argv.push_back("-b");
		argv.push_back("files:" + std::to_string(cfg.ring_files));
	}
	if(cfg.filesize_kb > 0) {
		argv.push_back("-b");
		argv.push_back("filesize:" + std::to_string(cfg.filesize_kb));
	}
	argv.push_back("-w");
	argv.push_back(cfg.output.string());
	return argv;
}

std::string build_command_string(const std::vector<std::string> &argv) {
	std::string out;
	for(std::size_t i = 0; i < argv.size(); ++i) {
		if(i != 0) {
			out.push_back(' ');
		}
		out += shell_quote(argv[i]);
	}
	return out;
}

} // namespace dumpcap
#include "dumpcap_command.h"

#include <filesystem>
#include <iostream>
#include <string>
#include <vector>

#include <unistd.h>

#include "cmdline.h"

namespace {

std::vector<char*> to_exec_argv(std::vector<std::string> &argv) {
	std::vector<char*> out;
	out.reserve(argv.size() + 1);
	for(auto &arg : argv) {
		out.push_back(arg.data());
	}
	out.push_back(nullptr);
	return out;
}

} // namespace

int main(int argc, char **argv) {
	cmdline::parser cp;
	cp.add<std::string>("config", 'c', "capture config json file", false, "");
	cp.add<std::string>("program", 0, "dumpcap program path", false, "dumpcap");
	cp.add<std::string>("interfaces", 'i', "comma-separated capture interfaces", false, "");
	cp.add("auto-interfaces", 0, "discover capture interfaces with dumpcap -D");
	cp.add("no-auto-interfaces", 0, "disable interface auto discovery");
	cp.add("include-loopback", 0, "include loopback interface in auto discovery");
	cp.add<std::string>("exclude-interfaces", 0, "comma-separated wildcard exclude patterns", false, "");
	cp.add<std::uint32_t>("ring-duration-sec", 0, "dumpcap ring duration in seconds", false, 0);
	cp.add<std::uint32_t>("ring-files", 0, "dumpcap ring file count", false, 20);
	cp.add<std::uint32_t>("filesize-kb", 0, "dumpcap ring file size in KiB", false, 20480);
	cp.add<std::string>("filter", 'f', "capture BPF filter", false, "not port 22");
	cp.add<std::string>("output", 'w', "capture output path", false, "/tmp/capture/cap.pcapng");
	cp.add("print-command", 0, "print command and exit instead of exec");
	cp.parse_check(argc, argv);

	dumpcap::config cfg;
	const auto config_path = cp.get<std::string>("config");
	if(!config_path.empty() && dumpcap::load_config_file(config_path, cfg) != 0) {
		return 1;
	}

	if(cp.exist("program")) cfg.program = cp.get<std::string>("program");
	if(!cp.get<std::string>("interfaces").empty()) cfg.interfaces = dumpcap::split_csv(cp.get<std::string>("interfaces"));
	if(cp.exist("auto-interfaces")) cfg.auto_interfaces = true;
	if(cp.exist("no-auto-interfaces")) cfg.auto_interfaces = false;
	if(cp.exist("include-loopback")) cfg.include_loopback = true;
	if(!cp.get<std::string>("exclude-interfaces").empty()) cfg.exclude_interfaces = dumpcap::split_csv(cp.get<std::string>("exclude-interfaces"));
	if(cp.exist("ring-duration-sec")) cfg.ring_duration_sec = cp.get<std::uint32_t>("ring-duration-sec");
	if(cp.exist("ring-files")) cfg.ring_files = cp.get<std::uint32_t>("ring-files");
	if(cp.exist("filesize-kb")) cfg.filesize_kb = cp.get<std::uint32_t>("filesize-kb");
	if(cp.exist("filter")) cfg.bpf_filter = cp.get<std::string>("filter");
	if(cp.exist("output")) cfg.output = cp.get<std::string>("output");

	dumpcap::resolved_config resolved;
	try {
		resolved = dumpcap::resolve_config(cfg);
	}
	catch(const std::exception &e) {
		std::cerr << "dumpcap_runner: " << e.what() << std::endl;
		return 1;
	}

	std::filesystem::create_directories(resolved.cfg.output.parent_path());
	auto exec_args = dumpcap::build_argv(resolved);
	if(cp.exist("print-command")) {
		std::cout << dumpcap::build_command_string(exec_args) << std::endl;
		return 0;
	}

	auto raw_args = to_exec_argv(exec_args);
	execvp(raw_args[0], raw_args.data());
	perror("execvp");
	return 127;
}
#include "interface.h"

#include <algorithm>
#include <filesystem>
#include <fstream>
#include <string_view>
#include <utility>

namespace netif {

interface::interface(interface_id id, event_sink &events)
	: m_id(std::move(id))
	, m_sysfs_path(std::filesystem::path("/sys/class/net") / m_id.name)
	, m_stats_path(m_sysfs_path / "statistics")
	, m_events(events) {
}

void interface::observe(std::uint32_t capture_id, std::string_view name) {
	m_id.capture_id = capture_id;
	m_id.has_capture_id = true;
	if(name.empty() == false && m_id.name != name) {
		m_id.name = std::string(name);
		m_sysfs_path = std::filesystem::path("/sys/class/net") / m_id.name;
		m_stats_path = m_sysfs_path / "statistics";
	}
}

bool interface::read_sysfs_string(const char *name, std::string &value) const {
	std::ifstream ifs(m_sysfs_path / name);
	if(ifs.good() == false) {
		return false;
	}

	ifs >> value;
	return ifs.fail() == false;
}

bool interface::read_sysfs_uint64(const char *name, std::uint64_t &value) const {
	std::ifstream ifs(m_sysfs_path / name);
	if(ifs.good() == false) {
		return false;
	}

	ifs >> value;
	return ifs.fail() == false;
}

bool interface::read_sysfs_int64(const char *name, std::int64_t &value) const {
	std::ifstream ifs(m_sysfs_path / name);
	if(ifs.good() == false) {
		return false;
	}

	ifs >> value;
	return ifs.fail() == false;
}

bool interface::read_stat(const char *name, std::uint64_t &value) const {
	std::ifstream ifs(m_stats_path / name);
	if(ifs.good() == false) {
		return false;
	}

	ifs >> value;
	return ifs.fail() == false;
}

bool interface::update_stat(const char *name, counter_value &counter) {
	std::uint64_t value = 0;
	if(read_stat(name, value) == false) {
		return false;
	}

	counter.update(value);
	return true;
}

void interface::update_link_info() {
	std::int64_t speed_mbps = 0;
	m_link.has_speed_mbps = read_sysfs_int64("speed", speed_mbps) && speed_mbps > 0;
	m_link.speed_mbps = m_link.has_speed_mbps ? static_cast<std::uint64_t>(speed_mbps) : 0;

	m_link.has_duplex = read_sysfs_string("duplex", m_link.duplex);
	m_link.has_operstate = read_sysfs_string("operstate", m_link.operstate);

	std::uint64_t carrier = 0;
	m_link.has_carrier = read_sysfs_uint64("carrier", carrier);
	m_link.carrier = m_link.has_carrier && carrier != 0;

	m_link.has_mtu = read_sysfs_uint64("mtu", m_link.mtu);
	m_link.has_mac = read_sysfs_string("address", m_link.mac);
}

json interface::make_link_json() const {
	return json{
		{"speed_mbps", m_link.has_speed_mbps ? json(m_link.speed_mbps) : json(nullptr)},
		{"duplex", m_link.has_duplex ? json(m_link.duplex) : json(nullptr)},
		{"operstate", m_link.has_operstate ? json(m_link.operstate) : json(nullptr)},
		{"carrier", m_link.has_carrier ? json(m_link.carrier) : json(nullptr)},
		{"mtu", m_link.has_mtu ? json(m_link.mtu) : json(nullptr)},
		{"mac", m_link.has_mac ? json(m_link.mac) : json(nullptr)},
	};
}

json interface::make_direction_metrics_json(const counter_value &bytes,
	double interval_sec,
	double capacity_bps) const {
	const bool has_bitrate = interval_sec > 0.0;
	const double bitrate_bps = has_bitrate
		? static_cast<double>(bytes.window) * 8.0 / interval_sec
		: 0.0;
	const bool has_capacity = has_bitrate && capacity_bps > 0.0;
	const double utilization = has_capacity ? bitrate_bps / capacity_bps : 0.0;
	const double headroom_bps = has_capacity ? std::max(0.0, capacity_bps - bitrate_bps) : 0.0;

	return json{
		{"bitrate_bps", has_bitrate ? json(bitrate_bps) : json(nullptr)},
		{"utilization", has_capacity ? json(utilization) : json(nullptr)},
		{"headroom_bps", has_capacity ? json(headroom_bps) : json(nullptr)},
	};
}

int interface::process(double now) {
	if(m_has_process_time) {
		m_interval_sec = now - m_last_process_time;
		if(m_interval_sec < 0.0) {
			m_interval_sec = 0.0;
		}
	}
	else {
		m_interval_sec = 0.0;
		m_has_process_time = true;
	}
	m_last_process_time = now;

	update_link_info();

	bool ok = true;
	ok = update_stat("rx_bytes", m_stats.rx_bytes) && ok;
	ok = update_stat("tx_bytes", m_stats.tx_bytes) && ok;
	ok = update_stat("rx_packets", m_stats.rx_packets) && ok;
	ok = update_stat("tx_packets", m_stats.tx_packets) && ok;
	ok = update_stat("rx_errors", m_stats.rx_errors) && ok;
	ok = update_stat("tx_errors", m_stats.tx_errors) && ok;
	ok = update_stat("rx_dropped", m_stats.rx_dropped) && ok;
	ok = update_stat("tx_dropped", m_stats.tx_dropped) && ok;
	m_available = ok;

	return 0;
}

int interface::update_events(double now) {
	(void)now;
	return 0;
}

int interface::append_metrics(double now, json::array_t &out) {
	(void)now;
	const double capacity_bps = m_link.has_speed_mbps
		? static_cast<double>(m_link.speed_mbps) * 1000.0 * 1000.0
		: 0.0;
	out.push_back(json{
		{"interface_id", m_id.has_capture_id ? json(m_id.capture_id) : json(nullptr)},
		{"observed", m_id.has_capture_id},
		{"name", m_id.name},
		{"available", m_available},
		{"link", make_link_json()},
		{"interval_sec", m_interval_sec},
		{"rx", {
			{"bytes", {
				{"window", m_stats.rx_bytes.window},
				{"total", m_stats.rx_bytes.total},
			}},
			{"rate", make_direction_metrics_json(m_stats.rx_bytes, m_interval_sec, capacity_bps)},
			{"packets", {
				{"window", m_stats.rx_packets.window},
				{"total", m_stats.rx_packets.total},
			}},
			{"errors", {
				{"window", m_stats.rx_errors.window},
				{"total", m_stats.rx_errors.total},
			}},
			{"dropped", {
				{"window", m_stats.rx_dropped.window},
				{"total", m_stats.rx_dropped.total},
			}},
		}},
		{"tx", {
			{"bytes", {
				{"window", m_stats.tx_bytes.window},
				{"total", m_stats.tx_bytes.total},
			}},
			{"rate", make_direction_metrics_json(m_stats.tx_bytes, m_interval_sec, capacity_bps)},
			{"packets", {
				{"window", m_stats.tx_packets.window},
				{"total", m_stats.tx_packets.total},
			}},
			{"errors", {
				{"window", m_stats.tx_errors.window},
				{"total", m_stats.tx_errors.total},
			}},
			{"dropped", {
				{"window", m_stats.tx_dropped.window},
				{"total", m_stats.tx_dropped.total},
			}},
		}},
	});
	return 0;
}

int interface::append_list(double now, json::array_t &out) {
	(void)now;
	out.push_back(json{
		{"interface_id", m_id.has_capture_id ? json(m_id.capture_id) : json(nullptr)},
		{"observed", m_id.has_capture_id},
		{"name", m_id.name},
		{"link", make_link_json()},
	});
	return 0;
}

interfaces::interfaces(config cfg, event_sink &events)
	: m_cfg(std::move(cfg))
	, m_events(events) {
	discover();
}

int interfaces::discover() {
	if(m_cfg.names.empty() == false) {
		for(const auto &name : m_cfg.names) {
			add_interface(interface_id{ .name = name });
		}
		return 0;
	}

	std::vector<std::string> names;
	for(const auto &entry : std::filesystem::directory_iterator("/sys/class/net")) {
		names.push_back(entry.path().filename().string());
	}
	std::sort(names.begin(), names.end());

	for(const auto &name : names) {
		add_interface(interface_id{ .name = name });
	}

	return 0;
}

int interfaces::add_interface(const interface_id &id) {
	if(id.name.empty()) {
		return 0;
	}

	if(m_interfaces.find(id) != m_interfaces.end()) {
		return 0;
	}

	m_interfaces.emplace(id, std::make_unique<interface>(id, m_events));
	return 0;
}

int interfaces::observe(std::uint32_t capture_id, std::string_view name) {
	if(name.empty()) {
		return 0;
	}

	if(auto it = m_interfaces_by_capture_id.find(capture_id); it != m_interfaces_by_capture_id.end()) {
		it->second->observe(capture_id, name);
		return 0;
	}

	interface_id named_id{ .name = std::string(name) };
	if(auto it = m_interfaces.find(named_id); it != m_interfaces.end()) {
		it->second->observe(capture_id, name);
		m_interfaces_by_capture_id[capture_id] = it->second.get();
		return 0;
	}

	interface_id id{
		.capture_id = capture_id,
		.name = std::string(name),
		.has_capture_id = true,
	};
	auto inserted = m_interfaces.emplace(id, std::make_unique<interface>(id, m_events));
	m_interfaces_by_capture_id[capture_id] = inserted.first->second.get();
	return 0;
}

int interfaces::process(double now) {
	for(auto& [id, iface] : m_interfaces) {
		(void)id;
		iface->process(now);
	}

	return 0;
}

int interfaces::update_events(double now) {
	for(auto& [id, iface] : m_interfaces) {
		(void)id;
		iface->update_events(now);
	}

	return 0;
}

int interfaces::append_metrics(double now, json::array_t &out) {
	for(auto& [id, iface] : m_interfaces) {
		(void)id;
		iface->append_metrics(now, out);
	}

	return 0;
}

int interfaces::append_list(double now, json::array_t &out) {
	for(auto& [id, iface] : m_interfaces) {
		(void)id;
		iface->append_list(now, out);
	}

	return 0;
}

