namespace netif {

interface::interface(interface_id id, event_sink &events)
	: m_id(std::move(id))
	, m_sysfs_path(std::filesystem::path("/sys/class/net") / m_id.name)
	, m_stats_path(m_sysfs_path / "statistics")
	, m_events(events) {
}

void interface::observe(std::uint32_t capture_id, std::string_view name) {
	m_id.capture_id = capture_id;
	m_id.has_capture_id = true;
	if(name.empty() == false && m_id.name != name) {
		m_id.name = std::string(name);
		m_sysfs_path = std::filesystem::path("/sys/class/net") / m_id.name;
		m_stats_path = m_sysfs_path / "statistics";
	}
}

bool interface::read_sysfs_string(const char *name, std::string &value) const {
	std::ifstream ifs(m_sysfs_path / name);
	if(ifs.good() == false) {
		return false;
	}

	ifs >> value;
	return ifs.fail() == false;
}

bool interface::read_sysfs_uint64(const char *name, std::uint64_t &value) const {
	std::ifstream ifs(m_sysfs_path / name);
	if(ifs.good() == false) {
		return false;
	}

	ifs >> value;
	return ifs.fail() == false;
}

bool interface::read_sysfs_int64(const char *name, std::int64_t &value) const {
	std::ifstream ifs(m_sysfs_path / name);
	if(ifs.good() == false) {
		return false;
	}

	ifs >> value;
	return ifs.fail() == false;
}

bool interface::read_stat(const char *name, std::uint64_t &value) const {
	std::ifstream ifs(m_stats_path / name);
	if(ifs.good() == false) {
		return false;
	}

	ifs >> value;
	return ifs.fail() == false;
}

bool interface::update_stat(const char *name, counter_value &counter) {
	std::uint64_t value = 0;
	if(read_stat(name, value) == false) {
		return false;
	}

	counter.update(value);
	return true;
}

void interface::update_link_info() {
	std::int64_t speed_mbps = 0;
	m_link.has_speed_mbps = read_sysfs_int64("speed", speed_mbps) && speed_mbps > 0;
	m_link.speed_mbps = m_link.has_speed_mbps ? static_cast<std::uint64_t>(speed_mbps) : 0;

	m_link.has_duplex = read_sysfs_string("duplex", m_link.duplex);
	m_link.has_operstate = read_sysfs_string("operstate", m_link.operstate);

	std::uint64_t carrier = 0;
	m_link.has_carrier = read_sysfs_uint64("carrier", carrier);
	m_link.carrier = m_link.has_carrier && carrier != 0;

	m_link.has_mtu = read_sysfs_uint64("mtu", m_link.mtu);
	m_link.has_mac = read_sysfs_string("address", m_link.mac);
}

json interface::make_link_json() const {
	return json{
		{"speed_mbps", m_link.has_speed_mbps ? json(m_link.speed_mbps) : json(nullptr)},
		{"duplex", m_link.has_duplex ? json(m_link.duplex) : json(nullptr)},
		{"operstate", m_link.has_operstate ? json(m_link.operstate) : json(nullptr)},
		{"carrier", m_link.has_carrier ? json(m_link.carrier) : json(nullptr)},
		{"mtu", m_link.has_mtu ? json(m_link.mtu) : json(nullptr)},
		{"mac", m_link.has_mac ? json(m_link.mac) : json(nullptr)},
	};
}

json interface::make_direction_metrics_json(const counter_value &bytes,
	double interval_sec,
	double capacity_bps) const {
	const bool has_bitrate = interval_sec > 0.0;
	const double bitrate_bps = has_bitrate
		? static_cast<double>(bytes.window) * 8.0 / interval_sec
		: 0.0;
	const bool has_capacity = has_bitrate && capacity_bps > 0.0;
	const double utilization = has_capacity ? bitrate_bps / capacity_bps : 0.0;
	const double headroom_bps = has_capacity ? std::max(0.0, capacity_bps - bitrate_bps) : 0.0;

	return json{
		{"bitrate_bps", has_bitrate ? json(bitrate_bps) : json(nullptr)},
		{"utilization", has_capacity ? json(utilization) : json(nullptr)},
		{"headroom_bps", has_capacity ? json(headroom_bps) : json(nullptr)},
	};
}

int interface::process(double now) {
	if(m_has_process_time) {
		m_interval_sec = now - m_last_process_time;
		if(m_interval_sec < 0.0) {
			m_interval_sec = 0.0;
		}
	}
	else {
		m_interval_sec = 0.0;
		m_has_process_time = true;
	}
	m_last_process_time = now;

	update_link_info();

	bool ok = true;
	ok = update_stat("rx_bytes", m_stats.rx_bytes) && ok;
	ok = update_stat("tx_bytes", m_stats.tx_bytes) && ok;
	ok = update_stat("rx_packets", m_stats.rx_packets) && ok;
	ok = update_stat("tx_packets", m_stats.tx_packets) && ok;
	ok = update_stat("rx_errors", m_stats.rx_errors) && ok;
	ok = update_stat("tx_errors", m_stats.tx_errors) && ok;
	ok = update_stat("rx_dropped", m_stats.rx_dropped) && ok;
	ok = update_stat("tx_dropped", m_stats.tx_dropped) && ok;
	m_available = ok;

	return 0;
}

int interface::update_events(double now) {
	(void)now;
	return 0;
}

int interface::append_metrics(double now, json::array_t &out) {
	(void)now;
	const double capacity_bps = m_link.has_speed_mbps
		? static_cast<double>(m_link.speed_mbps) * 1000.0 * 1000.0
		: 0.0;
	out.push_back(json{
		{"interface_id", m_id.has_capture_id ? json(m_id.capture_id) : json(nullptr)},
		{"observed", m_id.has_capture_id},
		{"name", m_id.name},
		{"available", m_available},
		{"link", make_link_json()},
		{"interval_sec", m_interval_sec},
		{"rx", {
			{"bytes", {
				{"window", m_stats.rx_bytes.window},
				{"total", m_stats.rx_bytes.total},
			}},
			{"rate", make_direction_metrics_json(m_stats.rx_bytes, m_interval_sec, capacity_bps)},
			{"packets", {
				{"window", m_stats.rx_packets.window},
				{"total", m_stats.rx_packets.total},
			}},
			{"errors", {
				{"window", m_stats.rx_errors.window},
				{"total", m_stats.rx_errors.total},
			}},
			{"dropped", {
				{"window", m_stats.rx_dropped.window},
				{"total", m_stats.rx_dropped.total},
			}},
		}},
		{"tx", {
			{"bytes", {
				{"window", m_stats.tx_bytes.window},
				{"total", m_stats.tx_bytes.total},
			}},
			{"rate", make_direction_metrics_json(m_stats.tx_bytes, m_interval_sec, capacity_bps)},
			{"packets", {
				{"window", m_stats.tx_packets.window},
				{"total", m_stats.tx_packets.total},
			}},
			{"errors", {
				{"window", m_stats.tx_errors.window},
				{"total", m_stats.tx_errors.total},
			}},
			{"dropped", {
				{"window", m_stats.tx_dropped.window},
				{"total", m_stats.tx_dropped.total},
			}},
		}},
	});
	return 0;
}

int interface::append_list(double now, json::array_t &out) {
	(void)now;
	out.push_back(json{
		{"interface_id", m_id.has_capture_id ? json(m_id.capture_id) : json(nullptr)},
		{"observed", m_id.has_capture_id},
		{"name", m_id.name},
		{"link", make_link_json()},
	});
	return 0;
}

interfaces::interfaces(config cfg, event_sink &events)
	: m_cfg(std::move(cfg))
	, m_events(events) {
	discover();
}

int interfaces::discover() {
	if(m_cfg.names.empty() == false) {
		for(const auto &name : m_cfg.names) {
			add_interface(interface_id{ .name = name });
		}
		return 0;
	}

	std::vector<std::string> names;
	for(const auto &entry : std::filesystem::directory_iterator("/sys/class/net")) {
		names.push_back(entry.path().filename().string());
	}
	std::sort(names.begin(), names.end());

	for(const auto &name : names) {
		add_interface(interface_id{ .name = name });
	}

	return 0;
}

int interfaces::add_interface(const interface_id &id) {
	if(id.name.empty()) {
		return 0;
	}

	if(m_interfaces.find(id) != m_interfaces.end()) {
		return 0;
	}

	m_interfaces.emplace(id, std::make_unique<interface>(id, m_events));
	return 0;
}

int interfaces::observe(std::uint32_t capture_id, std::string_view name) {
	if(name.empty()) {
		return 0;
	}

	if(auto it = m_interfaces_by_capture_id.find(capture_id); it != m_interfaces_by_capture_id.end()) {
		it->second->observe(capture_id, name);
		return 0;
	}

	interface_id named_id{ .name = std::string(name) };
	if(auto it = m_interfaces.find(named_id); it != m_interfaces.end()) {
		it->second->observe(capture_id, name);
		m_interfaces_by_capture_id[capture_id] = it->second.get();
		return 0;
	}

	interface_id id{
		.capture_id = capture_id,
		.name = std::string(name),
		.has_capture_id = true,
	};
	auto inserted = m_interfaces.emplace(id, std::make_unique<interface>(id, m_events));
	m_interfaces_by_capture_id[capture_id] = inserted.first->second.get();
	return 0;
}

int interfaces::process(double now) {
	for(auto& [id, iface] : m_interfaces) {
		(void)id;
		iface->process(now);
	}

	return 0;
}

int interfaces::update_events(double now) {
	for(auto& [id, iface] : m_interfaces) {
		(void)id;
		iface->update_events(now);
	}

	return 0;
}

int interfaces::append_metrics(double now, json::array_t &out) {
	for(auto& [id, iface] : m_interfaces) {
		(void)id;
		iface->append_metrics(now, out);
	}

	return 0;
}

int interfaces::append_list(double now, json::array_t &out) {
	for(auto& [id, iface] : m_interfaces) {
		(void)id;
		iface->append_list(now, out);
	}

	return 0;
}

