#include "metrics_common.h"

namespace netif {

struct config {
	std::vector<std::string> names;
};

struct interface_id {
	std::uint32_t capture_id{0};
	std::string name;
	bool has_capture_id{false};

	bool operator==(const interface_id &o) const noexcept {
		if(has_capture_id && o.has_capture_id) {
			return capture_id == o.capture_id;
		}
		return has_capture_id == o.has_capture_id && name == o.name;
	}
};

struct interface_id_hash {
	std::size_t operator()(const interface_id &v) const noexcept {
		if(v.has_capture_id) {
			return std::hash<std::uint32_t>{}(v.capture_id);
		}
		return std::hash<std::string>{}(v.name);
	}
};

struct counter_value {
	std::uint64_t window{0};
	std::uint64_t total{0};
	bool initialized{false};

	void update(std::uint64_t value) {
		if(initialized) {
			window = (value >= total) ? (value - total) : 0;
		}
		else {
			window = 0;
			initialized = true;
		}
		total = value;
	}
};

struct interface_stats {
	counter_value rx_bytes;
	counter_value tx_bytes;
	counter_value rx_packets;
	counter_value tx_packets;
	counter_value rx_errors;
	counter_value tx_errors;
	counter_value rx_dropped;
	counter_value tx_dropped;
};

struct interface_link_info {
	bool has_speed_mbps{false};
	std::uint64_t speed_mbps{0};
	bool has_duplex{false};
	std::string duplex;
	bool has_operstate{false};
	std::string operstate;
	bool has_carrier{false};
	bool carrier{false};
	bool has_mtu{false};
	std::uint64_t mtu{0};
	bool has_mac{false};
	std::string mac;
};

class interface {
public:
	explicit interface(interface_id id, event_sink &events);
	virtual ~interface() = default;

	void observe(std::uint32_t capture_id, std::string_view name);
	int process(double now);
	int update_events(double now);
	int append_metrics(double now, json::array_t &out);
	int append_list(double now, json::array_t &out);

private:
	bool read_sysfs_string(const char *name, std::string &value) const;
	bool read_sysfs_uint64(const char *name, std::uint64_t &value) const;
	bool read_sysfs_int64(const char *name, std::int64_t &value) const;
	void update_link_info();
	bool read_stat(const char *name, std::uint64_t &value) const;
	bool update_stat(const char *name, counter_value &counter);
	json make_link_json() const;
	json make_direction_metrics_json(const counter_value &bytes,
		double interval_sec,
		double capacity_bps) const;

	interface_id m_id;
	std::filesystem::path m_sysfs_path;
	std::filesystem::path m_stats_path;
	interface_link_info m_link;
	interface_stats m_stats;
	event_sink &m_events;
	bool m_available{false};
	bool m_has_process_time{false};
	double m_last_process_time{0.0};
	double m_interval_sec{0.0};
};

class interfaces {
public:
	explicit interfaces(config cfg, event_sink &events);
	virtual ~interfaces() = default;

	int observe(std::uint32_t capture_id, std::string_view name);
	int process(double now);
	int update_events(double now);
	int append_metrics(double now, json::array_t &out);
	int append_list(double now, json::array_t &out);

private:
	int discover();
	int add_interface(const interface_id &id);

	config m_cfg;
	event_sink &m_events;
	std::unordered_map<interface_id, std::unique_ptr<interface>, interface_id_hash> m_interfaces;
	std::unordered_map<std::uint32_t, interface*> m_interfaces_by_capture_id;
};

} // namespace netif

