#include "pcap_watch.h"
#ifndef PCAP_WATCH_H
#define PCAP_WATCH_H

#include <algorithm>
#include <array>
#include <deque>
#include <filesystem>
#include <functional>
#include <iostream>
#include <set>
#include <string>
#include <sys/inotify.h>
#include <sys/wait.h>
#include <unistd.h>
#include <vector>

class pcap_watch {
public:
	using callback_t = std::function<bool(const std::filesystem::path&)>;

	enum class backlog_trend {
		stable,
		increasing,
		decreasing,
	};

	struct config {
		std::filesystem::path watch_dir;
		std::string pcap_prefix{"cap_"};
		std::size_t ring_file_count{5};
		std::size_t backlog_trend_threshold{1};
		bool stop_on_callback_failure{false};
	};

	explicit pcap_watch(config cfg)
		: m_config(std::move(cfg)) {}

	void set_callback(callback_t callback) {
		m_callback = std::move(callback);
	}

	template<class T>
	void set_callback(T& instance, bool (T::*method)(const std::filesystem::path&)) {
		m_callback = [&instance, method](const std::filesystem::path& path) {
			return (instance.*method)(path);
		};
	}

	template<class T>
	void set_callback(const T& instance, bool (T::*method)(const std::filesystem::path&) const) {
		m_callback = [&instance, method](const std::filesystem::path& path) {
			return (instance.*method)(path);
		};
	}

	int run() {
		if(!m_callback) {
			std::cerr << "[ERROR] callback is not set" << std::endl;
			return 1;
		}

		int fd = inotify_init();
		if(fd < 0) {
			perror("inotify_init");
			return 1;
		}

		int wd = inotify_add_watch(fd, m_config.watch_dir.c_str(), IN_CLOSE_WRITE);
		if(wd < 0) {
			perror("inotify_add_watch");
			close(fd);
			return 1;
		}

		std::cout << "[START] Monitoring " << m_config.watch_dir << "..." << std::endl;
		if(!rescan_pcaps()) {
			inotify_rm_watch(fd, wd);
			close(fd);
			return 1;
		}

		std::array<char, 16 * 1024> event_buf{};
		bool keep_running = true;
		while(keep_running) {
			ssize_t len = read(fd, event_buf.data(), event_buf.size());
			if(len < 0) {
				break;
			}

			for(ssize_t offset = 0; offset < len;) {
				auto* event = reinterpret_cast<struct inotify_event*>(event_buf.data() + offset);
				offset += sizeof(struct inotify_event) + event->len;

				if(event->mask & IN_Q_OVERFLOW) {
					std::cerr << "[WARN] inotify queue overflow, rescanning directory" << std::endl;
					if(!rescan_pcaps()) keep_running = false;
					continue;
				}

				if(event->len > 0) {
					std::string filename = event->name;
					if(is_target_pcap(filename) && !m_processed_files.contains(filename)) {
						enqueue_pending(filename);
					if(!process_pending_pcaps()) {
						keep_running = false;
						break;
					}
					}
				}
			}
		}

		inotify_rm_watch(fd, wd);
		close(fd);

		return 0;
	}

private:
	bool is_target_pcap(const std::string& filename) const {
		return filename.find(m_config.pcap_prefix) != std::string::npos &&
		       filename.find(".pcap") != std::string::npos;
	}

	void remember_processed(const std::string& filename) {
		if(!m_processed_files.insert(filename).second) {
			return;
		}

		m_processed_order.push_back(filename);
		while(m_processed_order.size() > m_config.ring_file_count) {
			m_processed_files.erase(m_processed_order.front());
			m_processed_order.pop_front();
		}
	}

	void report_pending_count(std::size_t pending_count) {
		if(!m_has_last_pending_count) {
			std::cout << "[BACKLOG] pending=" << pending_count << std::endl;
			m_has_last_pending_count = true;
			m_last_pending_count = pending_count;
			return;
		}

		if(pending_count > m_last_pending_count) {
			++m_increase_streak;
			m_decrease_streak = 0;
			if(m_increase_streak >= m_config.backlog_trend_threshold &&
			   (m_backlog_trend != backlog_trend::increasing ||
			    (m_increase_streak % m_config.backlog_trend_threshold) == 0)) {
				std::cout << "[BACKLOG] pending=" << pending_count
				          << " (+" << (pending_count - m_last_pending_count) << ", increasing)"
				          << std::endl;
				m_backlog_trend = backlog_trend::increasing;
			}
		}
		else if(pending_count < m_last_pending_count) {
			++m_decrease_streak;
			m_increase_streak = 0;
			if(m_decrease_streak >= m_config.backlog_trend_threshold &&
			   (m_backlog_trend != backlog_trend::decreasing ||
			    (m_decrease_streak % m_config.backlog_trend_threshold) == 0)) {
				std::cout << "[BACKLOG] pending=" << pending_count
				          << " (-" << (m_last_pending_count - pending_count) << ", decreasing)"
				          << std::endl;
				m_backlog_trend = backlog_trend::decreasing;
			}
		}
		else {
			m_increase_streak = 0;
			m_decrease_streak = 0;
			if(m_backlog_trend != backlog_trend::stable) {
				std::cout << "[BACKLOG] pending=" << pending_count << " (stable)" << std::endl;
				m_backlog_trend = backlog_trend::stable;
			}
		}

		m_last_pending_count = pending_count;
	}

	void enqueue_pending(const std::string& filename) {
		if(m_processed_files.contains(filename) || !m_pending_files.insert(filename).second) {
			return;
		}

		m_pending_order.push_back(filename);
	}

	bool process_pending_pcaps() {
		report_pending_count(m_pending_order.size());

		while(!m_pending_order.empty()) {
			const std::string& filename = m_pending_order.front();
			if(m_callback(m_config.watch_dir / filename)) {
				remember_processed(filename);
				m_pending_files.erase(filename);
				m_pending_order.pop_front();
			}
			else {
				return !m_config.stop_on_callback_failure;
			}

			report_pending_count(m_pending_order.size());
		}
		return true;
	}

	bool rescan_pcaps() {
		std::vector<std::string> filenames;

		for(const auto& entry : std::filesystem::directory_iterator(m_config.watch_dir)) {
			if(!entry.is_regular_file()) {
				continue;
			}

			std::string filename = entry.path().filename().string();
			if(is_target_pcap(filename) &&
			   !m_processed_files.contains(filename) &&
			   !m_pending_files.contains(filename)) {
				filenames.push_back(std::move(filename));
			}
		}

		std::sort(filenames.begin(), filenames.end());
		if(!filenames.empty()) {
			filenames.pop_back();
		}
		for(const auto& filename : filenames) {
			enqueue_pending(filename);
		}

		return process_pending_pcaps();
	}

	config m_config;
	callback_t m_callback;
	std::set<std::string> m_processed_files;
	std::set<std::string> m_pending_files;
	std::deque<std::string> m_processed_order;
	std::deque<std::string> m_pending_order;
