#include "log_pipeline.h"

#include <chrono>
#include <cstdio>
#include <ctime>
#include <utility>

#include <unistd.h>

namespace {
std::string make_capture_id() {
	auto now = std::chrono::system_clock::now();
	auto sec = std::chrono::time_point_cast<std::chrono::seconds>(now);
	auto us = std::chrono::duration_cast<std::chrono::microseconds>(now - sec).count();
	std::time_t tt = std::chrono::system_clock::to_time_t(sec);
	std::tm tm{};
	gmtime_r(&tt, &tm);
	char buf[64];
	std::snprintf(buf, sizeof(buf), "%04d%02d%02dT%02d%02d%02dZ-%06lld-%d",
	              tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
	              tm.tm_hour, tm.tm_min, tm.tm_sec,
	              static_cast<long long>(us), static_cast<int>(getpid()));
	return buf;
}
} // namespace

log_pipeline::log_pipeline(config cfg)
	: m_cfg(std::move(cfg)) {
	if(!m_cfg.dir.empty()) std::filesystem::create_directories(m_cfg.dir);
	m_capture_id = make_capture_id();
	m_event_journal_writer = std::make_unique<time_rotating_writer>(
		"STM_EVENT_JOURNAL", m_cfg.resolve(m_cfg.event_journal_dir),
		m_cfg.journal_part_size_bytes, m_cfg.journal_retention_hours);
	m_metrics_journal_writer = std::make_unique<time_rotating_writer>(
		"STM_METRICS_JOURNAL", m_cfg.resolve(m_cfg.metrics_journal_dir),
		m_cfg.journal_part_size_bytes, m_cfg.journal_retention_hours);
	m_event_sink = std::make_unique<event_sink>();
	m_event_journal_sink = std::make_unique<event_journal_sink>(*m_event_journal_writer, m_capture_id);
	m_event_sink->add_consumer(*m_event_journal_sink);
}

event_sink& log_pipeline::events() {
	return *m_event_sink;
}

void log_pipeline::append_metrics_snapshot(const json &root) {
	const double time = root.value("time", 0.0);
	const auto emitted_now = std::chrono::duration<double>(
		std::chrono::system_clock::now().time_since_epoch()).count();
	json journal = root;
	journal["schema_version"] = 2;
	journal["record_type"] = "metrics_snapshot";
	journal["capture_id"] = m_capture_id;
	journal["record_id"] = m_capture_id + ":metrics:" + std::to_string(m_metrics_journal_seq);
	journal["seq"] = m_metrics_journal_seq++;
	journal["emitted_at"] = emitted_now;
	m_metrics_journal_writer->dump_at(time, journal);
}
