	std::unique_ptr<tsv_source> m_tsv_source;
	std::unique_ptr<stream_registry> m_streams;
	std::unique_ptr<netif::interfaces> m_interfaces;
	protocol_map m_protocol_map;
	metrics::second_boundary m_second_boundary;
	packet_reorder_buffer m_reorder;
	std::optional<tsv::ctx> m_reorder_tsv_ctx;

	bool on_tsv_header(std::string_view header) override;
	bool on_tsv_row(std::string_view row) override;
	void on_tsv_end() override;
	int process_ordered_line(tsv::ctx &tc, std::string_view line);
	void flush_reorder_ready();
	void flush_reorder_all();
