#endif /* MONITOR_H */
#include "monitor.h"

#include <memory>
#include <utility>

#include "packet_context.h"
#include "batch_tshark_source.h"
#include "continuous_tshark_source.h"
#include "trace.h"
#include "tshark_command.h"
#include "tsv.h"
#include "tsv_util.h"



monitor::monitor()
	: monitor(config{}) {
}

monitor::monitor(config cfg)
	: m_cfg(std::move(cfg)),
	  m_reorder(m_cfg.reorder_holdback_sec) {
	m_init_status = init();
}

monitor::~monitor() {
}

int monitor::init() {
	{
		std::ios::sync_with_stdio(false);
		std::cin.tie(nullptr);
	}

	if(m_cfg.protocol_map_file.empty() == false) {
		if(m_protocol_map.load(m_cfg.protocol_map_file) != 0) {
			return -1;
		}
	}


	m_logs = std::make_unique<log_pipeline>(m_cfg.log);
	m_alerts = std::make_unique<alert_evaluator>(m_logs->events());
	if(!m_cfg.alert_config_file.empty() && m_alerts->load(m_cfg.alert_config_file) != 0) {
		return -1;
	}

	m_streams = std::make_unique<stream_registry>(m_protocol_map, m_logs->events());
	m_interfaces = std::make_unique<netif::interfaces>(netif::config{}, m_logs->events());

	const batch_tshark_source::config source_cfg{
		.input = m_cfg.input,
		.tshark = m_cfg.tshark,
		.decode_as = m_protocol_map.decode_as_rules(),
	};
	if(m_cfg.mode == config::processing_mode::continuous) {
		m_tsv_source = std::make_unique<continuous_tshark_source>(continuous_tshark_source::config{
			.input = source_cfg.input, .tshark = source_cfg.tshark, .decode_as = source_cfg.decode_as});
	}
	else {
		m_tsv_source = std::make_unique<batch_tshark_source>(source_cfg);
	}

	return 0;
}

int monitor::run() {
	if(m_init_status != 0) {
		return 1;
	}
	if(!m_tsv_source) {
		trace(0, "error: TSV source is not initialized");
		return 1;
	}
	m_second_boundary.reset();
	m_reorder.reset();
	m_reorder_tsv_ctx.reset();

	const int rc = m_tsv_source->run(*this);
	flush_reorder_all();
	return rc;
}

bool monitor::on_tsv_header(std::string_view header) {
	tsv::ctx tc;
	const std::string header_text{header};
	if(!tsv::init_ctx(tc, header_text)) {
		return false;
	}
	if(m_reorder_tsv_ctx && m_reorder_tsv_ctx->h != tc.h) {
		trace(0, "warn: tshark field layout changed; flushing the packet reorder buffer");
		flush_reorder_all();
	}
	m_reorder_tsv_ctx = std::move(tc);
	trace(7, "%.*s", static_cast<int>(header.size()), header.data());
	return true;
}

bool monitor::on_tsv_row(std::string_view row_text) {
	if(!m_reorder_tsv_ctx) {
		trace(0, "warn: TSV row received before header");
		return false;
	}
	trace(7, "%.*s", static_cast<int>(row_text.size()), row_text.data());
	std::string buffered_line{row_text};
	tsv::row_t row;
	tsv::split(buffered_line, row);
	double time_epoch = 0.0;
	tsv::to_number(row[m_reorder_tsv_ctx->i.com.time_epoch], time_epoch);
	m_reorder.push(time_epoch, std::move(buffered_line));
	flush_reorder_ready();
	return true;
}

void monitor::on_tsv_end() {
}

void monitor::flush_reorder_ready() {
	if(!m_reorder_tsv_ctx) {
		return;
	}
	m_reorder.flush_ready([this](std::string_view ordered_line) {
		process_ordered_line(*m_reorder_tsv_ctx, ordered_line);
	});
}

void monitor::flush_reorder_all() {
	if(!m_reorder_tsv_ctx) {
		return;
	}
	m_reorder.flush_all([this](std::string_view ordered_line) {
		process_ordered_line(*m_reorder_tsv_ctx, ordered_line);
	});
}

int monitor::process_ordered_line(tsv::ctx &tc, std::string_view line) {
	tsv::row_t row;
	tsv::split(line, row);

	const packet_context packet = make_packet_context(tc, row);
	if(packet.dispatch_proto_changed()) {
		trace(4, "monitor: effective proto %s -> %s method=%s uri=%s status=%s",
		      packet.proto.c_str(),
		      packet.dispatch_proto.c_str(),
		      std::string(tsv::field_or_empty(row, tc.i.http.method)).c_str(),
		      std::string(tsv::field_or_empty(row, tc.i.http.uri)).c_str(),
		      std::string(tsv::field_or_empty(row, tc.i.http.status_code)).c_str());
	}

	m_interfaces->observe(packet.interface_id, packet.interface_name);

	m_streams->process_packet(tc, row, packet);

	auto br = m_second_boundary.update(packet.time_epoch);
	if(!br.changed) {
		return 0;
	}

	write_second_boundary_outputs(tc.r.com.time_epoch, packet);

	return 0;
}

void monitor::update_second_boundary_state(double now) {
	m_interfaces->process(now);
	m_streams->update_events(now);
	m_interfaces->update_events(now);
}

json monitor::build_metrics_root(double now, const packet_context &packet) {
	json::array_t metrics_list;
	m_streams->append_metrics(now, metrics_list);

	json::array_t interface_metrics;
	m_interfaces->append_metrics(now, interface_metrics);

	json root{
		{"time", now},
		{"metrics", std::move(metrics_list)},
		{"interfaces", std::move(interface_metrics)},
	};
	if(packet.vlan.empty() == false) {
		root["vlan"] = tsv::to_json(packet.vlan);
	}

	return root;
}

void monitor::evaluate_alerts(double now, const json &metrics_root) {
	if(!m_alerts || m_alerts->empty()) return;
	m_alerts->evaluate(now,
	                   metrics_root.at("metrics").get<json::array_t>(),
	                   metrics_root.at("interfaces").get<json::array_t>());
}

void monitor::write_second_boundary_outputs(double now, const packet_context &packet) {
	update_second_boundary_state(now);
	auto metrics_root = build_metrics_root(now, packet);
	evaluate_alerts(now, metrics_root);
	m_logs->append_metrics_snapshot(metrics_root);
}
import type { Server as HttpServer } from "node:http";
import { WebSocketServer, type WebSocket } from "ws";
import type { StreamStore } from "../state/store";
import type { AppConfig, WsMessage } from "../types";

export class SocketServer {
  private readonly wss = new WebSocketServer({ noServer: true });
  private readonly metricSubscriptions = new Map<WebSocket, string>();
  private pendingStreams = false;
  private connectionHeartbeatTimer: NodeJS.Timeout | null = null;
  private maintenanceTimer: NodeJS.Timeout | null = null;
  private streamSeq = 0;
  private lastStreams = new Map<string, string>();

  constructor(
    private readonly server: HttpServer,
    private readonly store: StreamStore,
    private readonly streamsPatchIntervalMs = 250,
    private readonly maxBufferedBytes = 8 * 1024 * 1024
  ) {}

  start() {
    this.server.on("upgrade", (request, socket, head) => {
      if (request.url !== "/ws") return;
      this.wss.handleUpgrade(request, socket, head, (ws) => {
        this.wss.emit("connection", ws, request);
      });
    });

    this.wss.on("connection", (ws) => {
      this.send(ws, {
        type: "snapshot",
        streams: this.store.listStreams(),
        interfaces: this.store.listInterfaces(),
        timeline: [],
        summary: this.store.getSummary(),
        streamsSeq: this.streamSeq
      });
      ws.on("message", (raw) => this.handleClientMessage(ws, raw.toString()));
      ws.on("close", () => this.metricSubscriptions.delete(ws));
    });

    this.store.on("streams:update", () => this.scheduleStreamsUpdate());
    this.store.on("metrics:update", (streamKey: string) => this.broadcastSubscribedMetrics(streamKey));

    this.store.on("events:update", (event) => {
      this.broadcast({ type: "events:update", events: [event] });
    });

    this.maintenanceTimer = setInterval(() => this.store.tick(), 1000);
    this.maintenanceTimer.unref?.();
    this.connectionHeartbeatTimer = setInterval(() => this.broadcast({ type: "connection:heartbeat" }), 5000);
    this.connectionHeartbeatTimer.unref?.();
  }

  broadcastConfig(config: AppConfig) {
    this.broadcast({ type: "config:update", config });
  }

  broadcastLiveHeartbeat() {
    this.broadcast({ type: "live:heartbeat" });
  }


  private scheduleStreamsUpdate() {
    if (this.pendingStreams) return;
    this.pendingStreams = true;
    setTimeout(() => {
      this.pendingStreams = false;
      const streams = this.store.listStreams();
      const order = streams.map((s) => s.streamKey);
      const nextMap = new Map<string, string>();
      const upserts = [];
      for (const stream of streams) {
        const encoded = JSON.stringify(stream);
        nextMap.set(stream.streamKey, encoded);
        if (this.lastStreams.get(stream.streamKey) !== encoded) {
          upserts.push(stream);
        }
      }
      const removes: string[] = [];
      for (const key of this.lastStreams.keys()) {
        if (!nextMap.has(key)) removes.push(key);
      }
      if (upserts.length === 0 && removes.length === 0) return;
      this.lastStreams = nextMap;
      this.streamSeq += 1;
      this.broadcast({
        type: "streams:patch",
        seq: this.streamSeq,
        upserts,
        removes,
        order,
        interfaces: this.store.listInterfaces(),
        summary: this.store.getSummary()
      });
    }, Math.max(50, this.streamsPatchIntervalMs));
  }

  private broadcast(message: WsMessage) {
    const clients = [...this.wss.clients].filter((client) => client.readyState === client.OPEN);
    if (clients.length === 0) return;
    const payload = JSON.stringify(message);
    for (const client of clients) this.safeSend(client, payload);
  }

  private broadcastSubscribedMetrics(streamKey: string) {
    const clients = [...this.wss.clients].filter((client) =>
      client.readyState === client.OPEN && this.metricSubscriptions.get(client) === streamKey
    );
    if (clients.length === 0) return;

    const metrics = this.store.getMetrics(streamKey);
    if (!metrics) return;

    const payload = JSON.stringify({ type: "stream:metrics", streamKey, metrics } satisfies WsMessage);
    for (const client of clients) this.safeSend(client, payload);
  }

  private handleClientMessage(client: WebSocket, raw: string) {
    try {
      const message = JSON.parse(raw) as { type?: string; streamKey?: unknown };
      if (message.type !== "stream:subscribe") return;
      if (typeof message.streamKey === "string" && message.streamKey.length > 0) {
        this.metricSubscriptions.set(client, message.streamKey);
      } else {
        this.metricSubscriptions.delete(client);
      }
    } catch {
      // Ignore malformed client messages; the connection can continue receiving snapshots.
    }
  }

  private send(client: WebSocket, message: WsMessage) {
    if (client.readyState === client.OPEN) this.safeSend(client, JSON.stringify(message));
  }

  private safeSend(client: WebSocket, payload: string) {
    if (client.bufferedAmount > this.maxBufferedBytes) {
      this.metricSubscriptions.delete(client);
      client.terminate();
      return;
    }
    client.send(payload);
  }
}
