{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://example.invalid/stm/alerts_config.schema.json",
  "title": "STM alerts_config.json",
  "description": "Schema for STM monitoring-policy configuration.",
  "type": "object",
  "additionalProperties": false,
  "required": ["policies", "bindings"],
  "properties": {
    "_note": { "type": "string" },
    "policies": { "type": "array", "items": { "$ref": "#/$defs/policy" } },
    "bindings": { "type": "array", "items": { "$ref": "#/$defs/binding" } }
  },
  "$defs": {
    "policy": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "conditions"],
      "properties": {
        "id": { "type": "string", "minLength": 1 },
        "title": { "type": "string" },
        "conditions": { "type": "array", "items": { "$ref": "#/$defs/alertRule" } }
      }
    },
    "binding": {
      "type": "object",
      "additionalProperties": false,
      "required": ["scope", "mode"],
      "properties": {
        "scope": {
          "type": "object",
          "additionalProperties": false,
          "required": ["kind"],
          "properties": {
            "kind": { "enum": ["protocol", "managed_target"] },
            "proto": { "type": "string" },
            "target": { "enum": ["any", "flow", "stream", "interface"] },
            "target_id": { "type": "string" },
            "target_type": { "enum": ["single", "group"] }
          }
        },
        "mode": { "enum": ["shared", "individual", "shared_with_adjustments", "disabled"] },
        "policy_id": { "type": "string", "minLength": 1 },
        "conditions": { "type": "array", "items": { "$ref": "#/$defs/alertRule" } },
        "adjustments": { "type": "object", "additionalProperties": { "type": "object" } },
        "additional_conditions": { "type": "array", "items": { "$ref": "#/$defs/alertRule" } }
      }
    },
    "alertRule": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "id",
        "metric"
      ],
      "properties": {
        "id": {
          "type": "string",
          "minLength": 1,
          "description": "Stable alert rule identifier. It is used as part of the alert state key."
        },
        "enabled": {
          "type": "boolean",
          "default": true,
          "description": "When false, the rule is loaded but not evaluated."
        },
        "target": {
          "type": "string",
          "enum": [
            "any",
            "flow",
            "stream",
            "interface"
          ],
          "default": "any",
          "description": "Evaluation target. flow requires flow_key; stream excludes flow entries; interface evaluates interface metrics."
        },
        "proto": {
          "type": "string",
          "enum": [
            "RTMP",
            "RTP",
            "SRT",
            "HLS"
          ],
          "description": "Optional protocol filter. Omit this field for protocol-independent rules such as OTHER-like or interface rules. HLS metrics marked x-ui-preview are frontend-only placeholders and are not emitted by the backend yet."
        },
        "flow_roles": {
          "type": "array",
          "uniqueItems": true,
          "items": { "type": "string", "minLength": 1 },
          "description": "Optional flow role filter. It applies only to flow target rules; omit to evaluate every role."
        },
        "metric": {
          "type": "string",
          "oneOf": [
            {
              "const": "bandwidth.avg",
              "description": "Average SRT bandwidth estimate decoder value. Unit follows the tshark SRT decoder output.",
              "x-unit": "decoder-unit"
            },
            {
              "const": "bandwidth.count",
              "description": "Number of SRT bandwidth estimate samples in the current statistics window.",
              "x-unit": "samples"
            },
            {
              "const": "bandwidth.max",
              "description": "Maximum SRT bandwidth estimate decoder value. Unit follows the tshark SRT decoder output.",
              "x-unit": "decoder-unit"
            },
            {
              "const": "bandwidth.min",
              "description": "Minimum SRT bandwidth estimate decoder value. Unit follows the tshark SRT decoder output.",
              "x-unit": "decoder-unit"
            },
            {
              "const": "bandwidth.value",
              "description": "Current SRT bandwidth estimate decoder value. Unit follows the tshark SRT decoder output.",
              "x-unit": "decoder-unit"
            },
            {
              "const": "bitrate.avg",
              "description": "Avg bitrate sample value in bits per second.",
              "x-unit": "bps"
            },
            {
              "const": "bitrate.bps",
              "description": "Current bitrate in bits per second.",
              "x-unit": "bps"
            },
            {
              "const": "bitrate.count",
              "description": "Number of bitrate samples in the current statistics window.",
              "x-unit": "samples"
            },
            {
              "const": "bitrate.max",
              "description": "Max bitrate sample value in bits per second.",
              "x-unit": "bps"
            },
            {
              "const": "bitrate.min",
              "description": "Min bitrate sample value in bits per second.",
              "x-unit": "bps"
            },
            {
              "const": "clock_skew.observed_rate",
              "description": "Observed RTP/RTMP timestamp clock rate in ticks per second.",
              "x-unit": "ticks/s"
            },
            {
