std::vector<std::string> split_path(const std::string &path) {
	std::vector<std::string> out;
	std::size_t start = 0;
	while(start <= path.size()) {
		const auto pos = path.find('.', start);
		const auto end = (pos == std::string::npos) ? path.size() : pos;
		if(end > start) {
			out.emplace_back(path.substr(start, end - start));
		}
		if(pos == std::string::npos) {
			break;
		}
		start = pos + 1;
	}
	return out;
}

std::string json_string_or_empty(const json &j, const char *key) {
	if(!j.is_object() || !j.contains(key) || j[key].is_null()) {
		return {};
	}
	if(j[key].is_string()) {
		return j[key].get<std::string>();
	}
	if(j[key].is_number_integer()) {
		return std::to_string(j[key].get<long long>());
	}
	if(j[key].is_number_unsigned()) {
		return std::to_string(j[key].get<unsigned long long>());
	}
	if(j[key].is_number_float()) {
		return std::to_string(j[key].get<double>());
	}
	return {};
}

bool read_bool(const json &j, const char *key, bool fallback) {
	if(!j.contains(key) || !j[key].is_boolean()) {
		return fallback;
	}
	return j[key].get<bool>();
}

