	if(!root.is_object() || !root.contains("policies") || !root["policies"].is_array() || !root.contains("bindings") || !root["bindings"].is_array()) {
		std::cerr << "alert_evaluator: monitoring policy format requires policies and bindings arrays" << std::endl;
		return -1;
