					b.scope_target = scope["target"].get<std::string>();
					if(b.scope_target != "any" && b.scope_target != "flow" && b.scope_target != "stream" && b.scope_target != "interface") throw std::runtime_error("protocol scope target is invalid");
					scope_has_target = true;
