#ifndef BATCH_TSHARK_SOURCE_H
#define BATCH_TSHARK_SOURCE_H

#include <memory>

#include "pcap_input_source.h"
#include "tshark_command.h"
#include "tsv_source.h"

class batch_tshark_source final : public tsv_source {
public:
	struct config {
		pcap_input::config input;
		tshark::read_config tshark;
		std::vector<std::string> decode_as;
	};

	explicit batch_tshark_source(config cfg);
	int run(tsv_sink &sink) override;

private:
	bool process_pcap(const std::filesystem::path &path, tsv_sink &sink);

	config m_cfg;
	std::unique_ptr<pcap_input::source> m_input;
};

#endif /* BATCH_TSHARK_SOURCE_H */
#include "batch_tshark_source.h"

#include <array>
#include <cstdio>
#include <sys/wait.h>

#include "trace.h"

batch_tshark_source::batch_tshark_source(config cfg)
	: m_cfg(std::move(cfg)),
	  m_input(pcap_input::make_source(m_cfg.input)) {
}

int batch_tshark_source::run(tsv_sink &sink) {
	if(!m_input) {
		trace(0, "error: failed to create batch pcap input source");
		return 1;
	}
	m_input->set_callback([this, &sink](const std::filesystem::path &path) {
		return process_pcap(path, sink);
	});
	return m_input->run();
}

bool batch_tshark_source::process_pcap(const std::filesystem::path &path, tsv_sink &sink) {
	const std::string command = tshark::build_read_command(path, m_cfg.tshark, m_cfg.decode_as);
	FILE *pipe = popen(command.c_str(), "r");
	if(!pipe) {
		trace(0, "warn: failed to start tshark for %s", path.filename().string().c_str());
		return false;
	}

	std::array<char, 32768> line{};
	bool ok = true;
	if(fgets(line.data(), static_cast<int>(line.size()), pipe) == nullptr) {
		trace(1, "info: tshark output is empty for %s", path.filename().string().c_str());
	}
	else if(!sink.on_tsv_header(line.data())) {
		ok = false;
	}
	while(ok && fgets(line.data(), static_cast<int>(line.size()), pipe) != nullptr) {
		ok = sink.on_tsv_row(line.data());
	}
	sink.on_tsv_end();

	const int status = pclose(pipe);
	if(status == -1) {
		trace(0, "warn: pclose failed for %s", path.filename().string().c_str());
		return false;
	}
	if(WIFEXITED(status) && WEXITSTATUS(status) == 0) return ok;
	if(WIFEXITED(status)) {
		trace(0, "warn: tshark failed for %s, exit_code=%d", path.filename().string().c_str(), WEXITSTATUS(status));
	}
	else if(WIFSIGNALED(status)) {
		trace(0, "warn: tshark terminated for %s, signal=%d", path.filename().string().c_str(), WTERMSIG(status));
	}
	else {
		trace(0, "warn: tshark ended unexpectedly for %s, status=%d", path.filename().string().c_str(), status);
	}
	return false;
}
#include "continuous_tshark_source.h"

#include <array>
#include <cerrno>
#include <csignal>
#include <cstdio>
#include <cstring>
#include <sys/wait.h>
#include <unistd.h>

#include "trace.h"

namespace {
bool write_all(int fd, const char *data, std::size_t size) {
	while(size > 0) {
		const auto n = ::write(fd, data, size);
		if(n < 0) {
			if(errno == EINTR) continue;
			return false;
		}
		data += n;
		size -= static_cast<std::size_t>(n);
	}
	return true;
}
} // namespace

continuous_tshark_source::continuous_tshark_source(config cfg)
	: m_cfg(std::move(cfg)) {
	m_cfg.input.stop_on_callback_failure = true;
	m_input = pcap_input::make_source(m_cfg.input);
}

continuous_tshark_source::~continuous_tshark_source() {
	stop();
}

int continuous_tshark_source::run(tsv_sink &sink) {
	if(m_cfg.input.input_mode != pcap_input::mode::watch_dir) {
		trace(0, "error: continuous input requires watch_dir mode");
		return 1;
	}
	if(!m_input || !start(sink)) return 1;
	m_input->set_callback([this](const std::filesystem::path &path) {
		return process_pcap(path);
	});
	const int rc = m_input->run();
	stop();
	return rc == 0 && m_reader_ok ? 0 : 1;
}

bool continuous_tshark_source::start(tsv_sink &sink) {
	// A terminated tshark must turn a subsequent pipe write into a recoverable error.
	signal(SIGPIPE, SIG_IGN);
	int stdin_pipe[2]{};
	int stdout_pipe[2]{};
	if(pipe(stdin_pipe) != 0 || pipe(stdout_pipe) != 0) {
		trace(0, "error: failed to create tshark pipes: %s", std::strerror(errno));
		return false;
	}
	const auto argv_values = tshark::build_continuous_argv(m_cfg.tshark, m_cfg.decode_as);
	std::vector<char *> argv;
	argv.reserve(argv_values.size() + 1);
	for(const auto &value : argv_values) argv.push_back(const_cast<char *>(value.c_str()));
	argv.push_back(nullptr);

	const auto pid = fork();
	if(pid == 0) {
		dup2(stdin_pipe[0], STDIN_FILENO);
		dup2(stdout_pipe[1], STDOUT_FILENO);
		close(stdin_pipe[0]); close(stdin_pipe[1]);
		close(stdout_pipe[0]); close(stdout_pipe[1]);
		execvp(argv[0], argv.data());
		_exit(127);
	}
	if(pid < 0) {
		trace(0, "error: failed to start tshark: %s", std::strerror(errno));
		close(stdin_pipe[0]); close(stdin_pipe[1]); close(stdout_pipe[0]); close(stdout_pipe[1]);
		return false;
	}
	close(stdin_pipe[0]);
	close(stdout_pipe[1]);
	m_pid = pid;
	m_stdin_fd = stdin_pipe[1];
	m_stdout_fd = stdout_pipe[0];
	m_reader_ok = true;
	m_reader = std::thread([this, &sink] { read_output(sink); });
	return true;
}

bool continuous_tshark_source::process_pcap(const std::filesystem::path &path) {
	if(!m_reader_ok || m_stdin_fd < 0) return false;
	int status{};
	if(waitpid(m_pid, &status, WNOHANG) == m_pid) {
		trace(0, "warn: continuous tshark exited before %s", path.filename().string().c_str());
		m_pid = -1;
		return false;
	}
	std::vector<char> bytes;
	std::string error;
	if(!m_streamer.append(path, bytes, error)) {
		trace(0, "warn: continuous pcap streamer failed: %s", error.c_str());
		return false;
	}
	if(bytes.empty()) return true;
	if(!write_all(m_stdin_fd, bytes.data(), bytes.size())) {
		trace(0, "warn: failed to write pcap stream for %s: %s", path.filename().string().c_str(), std::strerror(errno));
		return false;
	}
	return true;
}

void continuous_tshark_source::read_output(tsv_sink &sink) {
	FILE *stream = fdopen(m_stdout_fd, "r");
	if(!stream) {
		m_reader_ok = false;
		return;
	}
	m_stdout_fd = -1;
	std::array<char, 32768> line{};
	if(fgets(line.data(), static_cast<int>(line.size()), stream) != nullptr) {
		m_reader_ok = sink.on_tsv_header(line.data());
	}
	else {
		m_reader_ok = false;
	}
	while(m_reader_ok && fgets(line.data(), static_cast<int>(line.size()), stream) != nullptr) {
		m_reader_ok = sink.on_tsv_row(line.data());
	}
	sink.on_tsv_end();
	fclose(stream);
}

void continuous_tshark_source::stop() {
	if(m_stdin_fd >= 0) {
		close(m_stdin_fd);
		m_stdin_fd = -1;
	}
	if(m_pid > 0) {
		kill(m_pid, SIGTERM);
		int status{};
		waitpid(m_pid, &status, 0);
		m_pid = -1;
	}
	if(m_reader.joinable()) m_reader.join();
	if(m_stdout_fd >= 0) {
		close(m_stdout_fd);
		m_stdout_fd = -1;
	}
}
