#include "capture_health.h"

#include <algorithm>
#include <chrono>
#include <cerrno>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <limits>
#include <sstream>
#include <system_error>

#include <sys/timex.h>
#include <unistd.h>

namespace capture_health {
namespace {

double now_epoch() {
	return std::chrono::duration<double>(std::chrono::system_clock::now().time_since_epoch()).count();
}

std::string trim(std::string value) {
	const auto first = value.find_first_not_of(" \t\r\n");
	if(first == std::string::npos) return {};
	const auto last = value.find_last_not_of(" \t\r\n");
	return value.substr(first, last - first + 1);
}

bool read_text(const std::filesystem::path &path, std::string &out) {
	std::ifstream in(path);
	if(!in) return false;
	std::getline(in, out);
	out = trim(std::move(out));
	return !in.bad();
}

bool read_u64(const std::filesystem::path &path, std::uint64_t &out) {
	std::string text;
	if(!read_text(path, text) || text.empty()) return false;
	try {
		std::size_t consumed = 0;
		out = std::stoull(text, &consumed, 0);
		return consumed == text.size();
	}
	catch(...) {
		return false;
	}
}

json nullable_u64(const std::filesystem::path &path) {
	std::uint64_t value = 0;
	return read_u64(path, value) ? json(value) : json(nullptr);
}

std::vector<std::string> as_strings(const json &root, const char *key) {
	std::vector<std::string> result;
	if(!root.contains(key)) return result;
	const auto &value = root.at(key);
	if(value.is_string()) {
		std::stringstream stream(value.get<std::string>());
		std::string item;
		while(std::getline(stream, item, ',')) {
			item = trim(std::move(item));
			if(!item.empty()) result.push_back(std::move(item));
		}
	}
	else if(value.is_array()) {
		for(const auto &item : value) if(item.is_string() && !item.get<std::string>().empty()) result.push_back(item.get<std::string>());
	}
	return result;
}

std::filesystem::path resolve(const std::filesystem::path &base, const std::string &value) {
	const std::filesystem::path path(value);
	return path.is_absolute() ? path : base / path;
}

std::string fnv1a64(std::string_view value) {
	std::uint64_t hash = 14695981039346656037ULL;
	for(const unsigned char ch : value) {
		hash ^= ch;
		hash *= 1099511628211ULL;
	}
	std::ostringstream out;
	out << std::hex << std::setfill('0') << std::setw(16) << hash;
	return out.str();
}

std::string read_boot_id() {
	std::string value;
	return read_text("/proc/sys/kernel/random/boot_id", value) ? value : std::string{};
}

std::vector<std::string> discovered_interfaces() {
	std::vector<std::string> result;
	std::error_code error;
	for(const auto &entry : std::filesystem::directory_iterator("/sys/class/net", error)) {
		if(error) break;
		result.push_back(entry.path().filename().string());
	}
	std::sort(result.begin(), result.end());
	return result;
}

std::string symlink_name(const std::filesystem::path &path) {
	std::error_code error;
	auto target = std::filesystem::read_symlink(path, error);
	return error ? std::string{} : target.filename().string();
}

json read_latest_json(const std::filesystem::path &path) {
	std::ifstream in(path);
	if(!in) return json();
	std::string line;
	json result;
	while(std::getline(in, line)) {
		try { if(!trim(line).empty()) result = json::parse(line); }
		catch(...) { }
	}
	return result;
}

bool has_pcap_extension(const std::filesystem::path &path) {
	const auto ext = path.extension().string();
	return ext == ".pcap" || ext == ".pcapng";
}

} // namespace

int load_config_file(const std::filesystem::path &path, config &out, std::string &error) {
	std::ifstream in(path);
	if(!in) { error = "failed to open config " + path.string(); return -1; }
	json root;
	try { in >> root; }
	catch(const std::exception &e) { error = "failed to parse config: " + std::string(e.what()); return -1; }
	if(!root.is_object()) { error = "config root must be an object"; return -1; }
	const auto base = path.parent_path();
	const json *capture = root.contains("capture") && root["capture"].is_object() ? &root["capture"] : nullptr;
	const json *health = root.contains("capture_health") && root["capture_health"].is_object() ? &root["capture_health"] : nullptr;
	if(capture) {
		out.interfaces = as_strings(*capture, "interfaces");
		out.ring_files = capture->value("ring_files", out.ring_files);
		const auto output = capture->value("output", std::string{});
		if(!output.empty()) out.pcap_dir = resolve(base, output).parent_path();
	}
	std::filesystem::path logs_dir = base;
	if(root.contains("logs") && root["logs"].is_object()) {
		const auto dir = root["logs"].value("dir", std::string{});
		if(!dir.empty()) logs_dir = resolve(base, dir);
	}
	out.output_file = logs_dir / "capture-health" / "live.ndjson";
	out.event_file = logs_dir / "capture-health" / "events.ndjson";
	if(!health) return 0;
	out.enabled = health->value("enabled", out.enabled);
	out.interval_sec = health->value("interval_sec", out.interval_sec);
	out.stale_after_sec = health->value("stale_after_sec", out.stale_after_sec);
	out.host_id = health->value("host_id", out.host_id);
	out.include_multicast_details = health->value("include_multicast_details", out.include_multicast_details);
	out.require_synchronized_clock = health->value("require_synchronized_clock", out.require_synchronized_clock);
	out.expose_network_details = health->value("expose_network_details", out.expose_network_details);
	if(health->contains("interfaces")) out.interfaces = as_strings(*health, "interfaces");
	for(const auto &[key, target] : std::initializer_list<std::pair<const char *, std::filesystem::path *>>{
		{"pcap_dir", &out.pcap_dir}, {"capture_status_file", &out.capture_status_file}, {"output_file", &out.output_file}, {"event_file", &out.event_file}}) {
		const auto value = health->value(key, std::string{});
		if(!value.empty()) *target = resolve(logs_dir, value);
	}
	out.ring_files = health->value("ring_files", out.ring_files);
	if(out.interval_sec == 0) { error = "capture_health.interval_sec must be greater than zero"; return -1; }
	return 0;
}

bool write_live_file(const std::filesystem::path &path, const json &value, std::string &error) {
	std::error_code ec;
	std::filesystem::create_directories(path.parent_path(), ec);
	if(ec) { error = "failed to create " + path.parent_path().string() + ": " + ec.message(); return false; }
	const auto temporary = path.string() + "." + std::to_string(getpid()) + ".tmp";
	{
		std::ofstream out(temporary, std::ios::trunc);
		if(!out) { error = "failed to open " + temporary; return false; }
		out << value.dump() << '\n';
		if(!out) { error = "failed to write " + temporary; return false; }
	}
	std::filesystem::rename(temporary, path, ec);
	if(ec) { std::filesystem::remove(temporary); error = "failed to replace " + path.string() + ": " + ec.message(); return false; }
	return true;
}

collector::collector(config cfg) : m_cfg(std::move(cfg)) {
	if(m_cfg.host_id.empty()) {
		char host[256]{};
		if(gethostname(host, sizeof(host) - 1) == 0) m_cfg.host_id = host;
	}
}

json collector::counter(const std::string &key, std::uint64_t total) {
	json result{{"total", total}, {"delta", nullptr}};
	if(const auto it = m_previous.find(key); it != m_previous.end()) result["delta"] = total >= it->second ? json(total - it->second) : json(nullptr);
	m_previous[key] = total;
	return result;
}

json collector::collect_interface(const std::string &name) {
	const std::filesystem::path root = std::filesystem::path("/sys/class/net") / name;
	json result{{"name", name}, {"state", std::filesystem::exists(root) ? "ok" : "unknown"}};
	if(!std::filesystem::exists(root)) return result;
	std::string value;
	if(read_text(root / "operstate", value)) result["operstate"] = value;
	if(read_text(root / "duplex", value)) result["duplex"] = value;
	if(read_text(root / "address", value)) result["mac"] = value;
	result["speed_mbps"] = nullable_u64(root / "speed");
	result["mtu"] = nullable_u64(root / "mtu");
	std::uint64_t flags = 0;
	if(read_u64(root / "flags", flags)) {
		result["multicast_enabled"] = (flags & 0x1000U) != 0;
		result["promiscuous"] = (flags & 0x100U) != 0;
	}
	const auto master = symlink_name(root / "master");
	if(!master.empty()) result["master"] = master;
	std::size_t rx_queues = 0, tx_queues = 0;
	std::error_code error;
	for(const auto &entry : std::filesystem::directory_iterator(root / "queues", error)) {
		if(error) break;
		const auto queue = entry.path().filename().string();
		if(queue.rfind("rx-", 0) == 0) ++rx_queues;
		if(queue.rfind("tx-", 0) == 0) ++tx_queues;
	}
	result["queues"] = {{"rx", rx_queues}, {"tx", tx_queues}};
	json counters = json::object();
	for(const auto *metric : {"rx_bytes", "tx_bytes", "rx_packets", "tx_packets", "rx_errors", "tx_errors", "rx_dropped", "tx_dropped", "rx_missed_errors", "rx_over_errors", "rx_crc_errors", "rx_frame_errors", "rx_fifo_errors", "rx_length_errors", "tx_carrier_errors", "tx_fifo_errors"}) {
		std::uint64_t number = 0;
		if(read_u64(root / "statistics" / metric, number)) counters[metric] = counter(name + ":" + metric, number);
	}
	result["counters"] = std::move(counters);
	return result;
}

json collector::collect_softnet() {
	std::ifstream in("/proc/net/softnet_stat");
	if(!in) return {{"state", "unknown"}};
	std::uint64_t processed = 0, dropped = 0, squeezed = 0;
	std::size_t cpus = 0;
	std::string line;
	while(std::getline(in, line)) {
		std::istringstream fields(line);
		std::string p, d, s;
		if(!(fields >> p >> d >> s)) continue;
		try {
			processed += std::stoull(p, nullptr, 16);
			dropped += std::stoull(d, nullptr, 16);
			squeezed += std::stoull(s, nullptr, 16);
			++cpus;
		}
		catch(...) { }
	}
	return {{"state", "ok"}, {"cpus", cpus}, {"processed", counter("softnet:processed", processed)}, {"dropped", counter("softnet:dropped", dropped)}, {"time_squeeze", counter("softnet:time_squeeze", squeezed)}};
}

json collector::collect_pipeline() const {
	json result{{"state", "unknown"}, {"pcap_dir", m_cfg.pcap_dir.string()}, {"ring_files", m_cfg.ring_files}};
	if(m_cfg.pcap_dir.empty() || !std::filesystem::is_directory(m_cfg.pcap_dir)) return result;
	std::size_t pcap_files = 0;
	std::filesystem::file_time_type newest{};
	std::error_code error;
	for(const auto &entry : std::filesystem::directory_iterator(m_cfg.pcap_dir, error)) {
		if(error || !entry.is_regular_file() || !has_pcap_extension(entry.path())) continue;
		++pcap_files;
		const auto time = entry.last_write_time(error);
		if(!error && time > newest) newest = time;
	}
	result["state"] = "ok";
	result["pcap_files"] = pcap_files;
	if(newest != std::filesystem::file_time_type{}) {
		const auto age = std::chrono::duration<double>(std::filesystem::file_time_type::clock::now() - newest).count();
		result["newest_file_age_sec"] = std::max(0.0, age);
	}
	if(!m_cfg.capture_status_file.empty()) {
		const auto status = read_latest_json(m_cfg.capture_status_file);
		result["capture_status"] = status.is_object() ? status : json(nullptr);
	}
	return result;
}

json collector::collect_clock() const {
	struct timex value {};
	if(adjtimex(&value) < 0) return {{"state", "unknown"}};
	const bool synchronized = (value.status & STA_UNSYNC) == 0;
	return {{"state", synchronized ? "ok" : "warning"}, {"synchronized", synchronized}, {"offset_us", value.offset}, {"maxerror_us", value.maxerror}, {"esterror_us", value.esterror}};
}

json collector::collect() {
	const auto observed_at = now_epoch();
	const auto names = m_cfg.interfaces.empty() ? discovered_interfaces() : m_cfg.interfaces;
	json interfaces = json::array();
	bool carrier_down = false;
	bool interface_errors = false;
	for(const auto &name : names) {
		auto item = collect_interface(name);
		if(item.value("operstate", std::string{}) == "down") carrier_down = true;
		for(const auto &metric : {"rx_errors", "tx_errors", "rx_dropped", "tx_dropped", "rx_missed_errors", "rx_over_errors", "rx_crc_errors", "rx_fifo_errors"}) {
			if(item.contains("counters") && item["counters"].contains(metric) && item["counters"][metric].value("delta", 0ULL) > 0) interface_errors = true;
		}
		interfaces.push_back(std::move(item));
	}
	const auto softnet = collect_softnet();
	const auto kernel_pressure = softnet.value("dropped", json::object()).value("delta", 0ULL) > 0 || softnet.value("time_squeeze", json::object()).value("delta", 0ULL) > 0;
	const auto clock = collect_clock();
	json sysctls = json::object();
	for(const auto *name : {"rmem_default", "rmem_max", "netdev_max_backlog", "netdev_budget", "netdev_budget_usecs", "rps_sock_flow_entries"}) sysctls[name] = nullable_u64(std::filesystem::path("/proc/sys/net/core") / name);
	json reasons = json::array();
	std::string state = "ok";
	if(carrier_down) { state = "critical"; reasons.push_back({{"component", "interface"}, {"code", "carrier_down"}}); }
	if(interface_errors && state != "critical") { state = "warning"; reasons.push_back({{"component", "interface"}, {"code", "counter_increase"}}); }
	if(kernel_pressure && state != "critical") { state = "warning"; reasons.push_back({{"component", "kernel"}, {"code", "softnet_pressure"}}); }
	if(m_cfg.require_synchronized_clock && !clock.value("synchronized", false) && state != "critical") { state = "warning"; reasons.push_back({{"component", "clock"}, {"code", "unsynchronized"}}); }
	json root{
		{"schema_version", 1}, {"record_type", "capture_health"}, {"observed_at", observed_at},
		{"host", {{"id", m_cfg.host_id}, {"boot_id", read_boot_id()}}},
		{"overall", {{"state", state}, {"reasons", std::move(reasons)}}},
		{"interfaces", std::move(interfaces)},
		{"kernel", {{"softnet", softnet}, {"sysctls", std::move(sysctls)}}},
		{"pipeline", collect_pipeline()},
		{"media_network", {{"clock", clock}, {"multicast_details_enabled", m_cfg.include_multicast_details}}}
	};
	return root;
}

bool collector::write_transition_event(const json &snapshot, std::string &error) {
	const auto state = snapshot.at("overall").value("state", std::string{"unknown"});
	if(m_previous_state.empty()) { m_previous_state = state; return true; }
	if(state == m_previous_state) return true;
	std::error_code ec;
	std::filesystem::create_directories(m_cfg.event_file.parent_path(), ec);
	if(ec) { error = "failed to create event directory: " + ec.message(); return false; }
	std::ofstream out(m_cfg.event_file, std::ios::app);
	if(!out) { error = "failed to open event file " + m_cfg.event_file.string(); return false; }
	out << json{{"schema_version", 1}, {"record_type", "capture_health_event"}, {"time", snapshot.value("observed_at", now_epoch())}, {"type", state == "ok" ? "capture_health_recovered" : "capture_health_state_changed"}, {"source", snapshot.at("host")}, {"detail", {{"from", m_previous_state}, {"to", state}, {"reasons", snapshot.at("overall").at("reasons")}}}}.dump() << '\n';
	m_previous_state = state;
	return static_cast<bool>(out);
}

