      const backfillFrom = from;
      let backfillCursorTo = Math.max(from, to - 3600);
      void getEvents({
        from: Math.max(from, to - 3600),
        to,
        limit: 10000
      }).then((recent) => {
        if (cancelled || seq !== loadSeq) return;
        eventsLoadedRef.current = true;
        setEvents(limitEvents(recent.sort((a, b) => b.time - a.time)));
        const runBackfill = async () => {
          while (!cancelled && seq === loadSeq && currentBackfillSeq === backfillTaskSeq && backfillCursorTo > backfillFrom) {
            const chunkTo = backfillCursorTo;
            const chunkFrom = Math.max(backfillFrom, chunkTo - 3600);
            backfillCursorTo = chunkFrom;
            const chunk = await getEvents({
              from: chunkFrom,
              to: chunkTo,
              limit: 10000
            });
            if (cancelled || seq !== loadSeq || currentBackfillSeq !== backfillTaskSeq) return;
            setEvents((current) => {
              const merged = new Map<string, EventLogItem>();
              for (const item of current) merged.set(item.id, item);
              for (const item of chunk) merged.set(item.id, item);
              return limitEvents([...merged.values()].sort((a, b) => b.time - a.time));
            });
          }
        };
        void runBackfill();
      }).catch(() => undefined).finally(() => {
        if (!cancelled && seq === loadSeq) setEventsLoading(false);
      });
    };

