				m_pending_order.pop_front();
			}
			else {
				return !m_config.stop_on_callback_failure;
			}

			report_pending_count(m_pending_order.size());
		}
		return true;
	}

	bool rescan_pcaps() {
		std::vector<std::string> filenames;

		for(const auto& entry : std::filesystem::directory_iterator(m_config.watch_dir)) {
			if(!entry.is_regular_file()) {
				continue;
			}

			std::string filename = entry.path().filename().string();
			if(is_target_pcap(filename) &&
			   !m_processed_files.contains(filename) &&
			   !m_pending_files.contains(filename)) {
				filenames.push_back(std::move(filename));
			}
		}

		std::sort(filenames.begin(), filenames.end());
		if(!filenames.empty()) {
			filenames.pop_back();
		}
		for(const auto& filename : filenames) {
			enqueue_pending(filename);
		}

		return process_pending_pcaps();
	}

	config m_config;
	callback_t m_callback;
	std::set<std::string> m_processed_files;
	std::set<std::string> m_pending_files;
	std::deque<std::string> m_processed_order;
	std::deque<std::string> m_pending_order;
	bool m_has_last_pending_count{false};
	std::size_t m_last_pending_count{0};
	backlog_trend m_backlog_trend{backlog_trend::stable};
	std::size_t m_increase_streak{0};
	std::size_t m_decrease_streak{0};
};

