std::string shell_quote(std::string_view value) {
	std::string quoted;
	quoted.reserve(value.size() + 2);
	quoted.push_back('\'');
	for(char ch : value) {
		if(ch == '\'') {
			quoted += "'\\''";
		}
		else {
			quoted.push_back(ch);
		}
	}
	quoted.push_back('\'');
	return quoted;
}

std::vector<std::string> split_csv(std::string_view value) {
	std::vector<std::string> out;
	std::size_t start = 0;
	while(start <= value.size()) {
		const auto pos = value.find(',', start);
		const auto end = (pos == std::string_view::npos) ? value.size() : pos;
		auto item = trim(value.substr(start, end - start));
		if(!item.empty()) {
			out.push_back(std::move(item));
		}
		if(pos == std::string_view::npos) {
			break;
		}
		start = pos + 1;
	}
	return out;
}

