	if(j->contains("ring_files")) cfg.ring_files = (*j)["ring_files"].get<std::uint32_t>();
	if(j->contains("filesize_kb")) cfg.filesize_kb = (*j)["filesize_kb"].get<std::uint32_t>();
	if(j->contains("buffer_size_mib")) cfg.buffer_size_mib = (*j)["buffer_size_mib"].get<std::uint32_t>();
	if(j->contains("report_statistics")) cfg.report_statistics = (*j)["report_statistics"].get<bool>();
	if(j->contains("bpf_filter")) cfg.bpf_filter = (*j)["bpf_filter"].get<std::string>();
	if(j->contains("output")) cfg.output = (*j)["output"].get<std::string>();
