	return 0;
}

std::vector<std::string> discover_interfaces(const std::string &program) {
	std::vector<std::string> out;
	const std::string command = shell_quote(program) + " -D 2>/dev/null";
	FILE *pipe = popen(command.c_str(), "r");
	if(pipe == nullptr) {
		return out;
	}

	std::array<char, 4096> buf{};
	while(fgets(buf.data(), static_cast<int>(buf.size()), pipe) != nullptr) {
		std::string line(buf.data());
		const auto dot = line.find('.');
		if(dot == std::string::npos) {
			continue;
		}
		std::string rest = trim(std::string_view(line).substr(dot + 1));
		if(rest.empty()) {
			continue;
		}
		std::istringstream iss(rest);
		std::string name;
		iss >> name;
		if(!name.empty()) {
			out.push_back(name);
		}
	}
	pclose(pipe);
	return out;
}

