import type { CaptureHealthCounter, CaptureHealthSnapshot, CaptureHealthState } from "../types/api";
import { useI18n } from "../i18n";
import { formatNumber, formatRelativeTime } from "./format";
import { PaneFrame, PaneHeader } from "./ui/PaneHeader";

export function CaptureHealthPane({ snapshot }: { snapshot: CaptureHealthSnapshot | null }) {
  const { t } = useI18n();
  if (!snapshot || snapshot.observed_at === 0) return <PaneFrame className="capture-health-frame" header={<PaneHeader title={t("nav.captureHealth")} icon="captureHealth" meta={t("captureHealth.waiting")} />}><div className="capture-health-empty">{t("captureHealth.waiting")}</div></PaneFrame>;
  const softnet = record(snapshot.kernel.softnet);
  const sysctls = snapshot.kernel.sysctls ?? {};
  const clock = record(snapshot.media_network.clock);
  const multicast = record(snapshot.media_network.multicast);
  const pipeline = snapshot.pipeline;
  return <PaneFrame className="capture-health-frame" header={<PaneHeader title={t("nav.captureHealth")} icon="captureHealth" meta={`${snapshot.host.id} · ${formatRelativeTime(snapshot.observed_at)}`} />}>
    <div className="capture-health-content">
      <section className={`capture-health-overall state-${snapshot.overall.state}`}>
        <div><p>{t("captureHealth.integrity")}</p><strong>{stateLabel(t, snapshot.overall.state)}</strong><span>{snapshot.overall.reasons.length ? snapshot.overall.reasons.map((item) => `${item.component}: ${item.code}`).join(" · ") : t("captureHealth.noActiveIssues")}</span></div>
        <dl><div><dt>{t("captureHealth.updated")}</dt><dd>{formatRelativeTime(snapshot.observed_at)}</dd></div><div><dt>{t("captureHealth.host")}</dt><dd>{snapshot.host.id}</dd></div><div><dt>{t("captureHealth.interfaces")}</dt><dd>{snapshot.interfaces.length}</dd></div></dl>
      </section>

      <section className="capture-health-section"><header><h3>{t("captureHealth.pipeline")}</h3><span>{stringValue(pipeline.state) ?? t("captureHealth.unknown")}</span></header><div className="capture-health-stats">
        <Stat label={t("captureHealth.pcapFiles")} value={formatValue(pipeline.pcap_files)} />
        <Stat label={t("captureHealth.pendingFiles")} value={formatValue(pipeline.pending_files)} />
        <Stat label={t("captureHealth.ringFiles")} value={formatValue(pipeline.ring_files)} />
        <Stat label={t("captureHealth.newestFile")} value={ageValue(pipeline.oldest_pending_age_sec ?? pipeline.newest_file_age_sec)} />
        <Stat label={t("captureHealth.captureStatus")} value={captureStatus(pipeline.capture_status, t)} />
      </div></section>

      <section className="capture-health-section"><header><h3>{t("captureHealth.interfaces")}</h3><span>{t("captureHealth.counterDelta")}</span></header><div className="capture-health-interface-table-wrap"><table className="capture-health-interface-table"><thead><tr><th>{t("captureHealth.interface")}</th><th>{t("captureHealth.link")}</th><th>RX drop</th><th>RX error</th><th>{t("captureHealth.queues")}</th><th>{t("captureHealth.network")}</th></tr></thead><tbody>{snapshot.interfaces.map((item) => <tr key={item.name} className={`state-${item.state}`}><td><span className="capture-health-state-dot" /><strong>{item.name}</strong><small>{item.operstate ?? t("captureHealth.unknown")}</small></td><td>{linkValue(item)}</td><td>{counterValue(item.counters?.rx_dropped)}</td><td>{counterValue(item.counters?.rx_errors)}</td><td>{item.queues ? `${item.queues.rx} RX / ${item.queues.tx} TX` : "-"}</td><td>{networkValue(item, t)}</td></tr>)}</tbody></table></div></section>

      <div className="capture-health-details-grid"><section className="capture-health-section"><header><h3>{t("captureHealth.kernel")}</h3><span>{stringValue(softnet?.state) ?? t("captureHealth.unknown")}</span></header><dl className="capture-health-definition"><div><dt>softnet dropped</dt><dd>{counterValue(counter(softnet?.dropped))}</dd></div><div><dt>time squeeze</dt><dd>{counterValue(counter(softnet?.time_squeeze))}</dd></div>{Object.entries(sysctls).map(([name, value]) => <div key={name}><dt>{name}</dt><dd>{formatValue(value)}</dd></div>)}</dl></section>
      <section className="capture-health-section"><header><h3>{t("captureHealth.mediaNetwork")}</h3><span>{stringValue(clock?.state) ?? t("captureHealth.unknown")}</span></header><dl className="capture-health-definition"><div><dt>{t("captureHealth.clockSync")}</dt><dd>{clock?.synchronized === true ? t("captureHealth.synchronized") : clock?.synchronized === false ? t("captureHealth.unsynchronized") : "-"}</dd></div><div><dt>{t("captureHealth.clockOffset")}</dt><dd>{formatValue(clock?.offset_us, " µs")}</dd></div><div><dt>{t("captureHealth.multicast")}</dt><dd>{formatValue(multicast?.group_count)} {t("captureHealth.groups")}</dd></div><div><dt>PTP</dt><dd>{formatValue(clock?.ptp_devices)} {t("captureHealth.devices")}</dd></div></dl></section></div>
    </div>
  </PaneFrame>;
}

function Stat({ label, value }: { label: string; value: string }) { return <div><span>{label}</span><strong>{value}</strong></div>; }
function record(value: unknown): Record<string, any> | undefined { return value && typeof value === "object" && !Array.isArray(value) ? value as Record<string, any> : undefined; }
function counter(value: unknown): CaptureHealthCounter | undefined { const item = record(value); return item && typeof item.total === "number" ? { total: item.total, delta: typeof item.delta === "number" ? item.delta : null } : undefined; }
function counterValue(value: CaptureHealthCounter | undefined) { return value ? `${formatNumber(value.delta ?? undefined)} / ${formatNumber(value.total)}` : "-"; }
function formatValue(value: unknown, suffix = "") { return typeof value === "number" && Number.isFinite(value) ? formatNumber(value) + suffix : typeof value === "string" ? value : "-"; }
function ageValue(value: unknown) { return typeof value === "number" && Number.isFinite(value) ? `${formatNumber(value)} s` : "-"; }
function stringValue(value: unknown) { return typeof value === "string" ? value : undefined; }
function captureStatus(value: unknown, t: (key: string) => string) { const item = record(value); return stringValue(item?.state) ?? t("captureHealth.unknown"); }
function stateLabel(t: (key: string) => string, state: CaptureHealthState) { return t(`captureHealth.state.${state}`); }
function linkValue(item: CaptureHealthSnapshot["interfaces"][number]) { const speed = item.speed_mbps ? `${item.speed_mbps}M` : "-"; return [item.carrier === true ? "carrier" : item.carrier === false ? "no carrier" : "", speed, item.duplex].filter(Boolean).join(" / ") || "-"; }
function networkValue(item: CaptureHealthSnapshot["interfaces"][number], t: (key: string) => string) { return [item.multicast_enabled ? t("captureHealth.multicast") : "", item.promiscuous ? "promisc" : "", item.master].filter(Boolean).join(" / ") || "-"; }
