item.stdout:
  color: var(--text-strong);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-compact);
}

.list-toolbar p,
.timeline-header p,
.topology-header p,
.dashboard-toolbar p {
  margin: 0;
  color: var(--muted);
  font-size: var(--font-size-xs);
}

.dashboard-toolbar {
  margin: 0;
}

/* A tab and a dashboard cell share the same flat header/body boundary. */
.main-tab-view {
  min-height: 0;
  height: 100%;
  padding: var(--space-3);
  overflow: hidden;
}

.main-tab-view > .pane-frame,
.main-tab-view > .standalone-view {
  min-height: 0;
  height: 100%;
}

.pane-frame {
  container-type: inline-size;
  min-height: 0;
  height: 100%;
  display: grid;
  grid-template-rows: var(--pane-header-height) minmax(0, 1fr);
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  background: var(--surface);
}

.pane-frame > .pane-header {
  min-height: var(--pane-header-height);
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
}

.pane-body {
  min-height: 0;
  overflow: hidden;
  background: var(--surface);
}

.pane-header-actions {
  justify-content: flex-end;
  flex-wrap: wrap;
  margin-left: auto;
}

.pane-search {
  width: var(--pane-search-width, min(240px, 26vw));
}

.streams-tab-frame .pane-body,
.timeline-tab-frame .pane-body {
  display: grid;
}

.streams-tab-frame .stream-table,
.timeline-tab-frame .pane-timeline-body {
  min-height: 0;
  height: 100%;
}

.timeline-tab-frame .pane-timeline-body {
  overflow: auto;
}
